comms.text:
@1 וְאִלֵּין תּוּלְדַת יִצְחָק בַּר אַבְרָהָם אַבְרָהָם אוֹלִיד יָת יִצְחָק:
@2 וַהֲוָה יִצְחָק בַּר אַרְבְּעִין שְׁנִין כַּד נְסֵיב יָת רִבְקָה בַּת בְּתוּאֵל אֲרַמָּאָה מִפַּדַּן אֲרָם אֲחָתֵהּ דְלָבָן אֲרַמָּאָה לֵהּ לְאִנְתּוּ:
@3 וְצַלִּי יִצְחָק קֳדָם יְיָ לָקֳבֵל אִתְּתֵהּ אֲרֵי עֲקָרָה הִיא וְקַבֵּל צְלוֹתֵהּ יְיָ וְעַדִּיאַת רִבְקָה אִתְּתֵהּ:
@4 וְדַחֲקִין בְּנַיָּא בִּמְעָהָא וַאֲמֶרֶת אִם כֵּן לְמָה דְּנַן אֲנָא וַאֲזָלַת לְמִתְבַּע אוּלְפַן מִן קֳדָם יְיָ:
@5 וַאֲמַר יְיָ לַהּ תְּרֵין עַמְמִין בִּמְעַיְכִי וְתַרְתֵּין מַלְכְּוָן מִמֵעַיְכִי יִתְפָּרְשָׁן וּמַלְכוּ מִמַלְכוּ יִתְקַף וְרַבָּא יִשְׁתַּעֲבֵּיד לִזְעֵירָא:
@6 וּשְׁלִימוּ יוֹמָהָא לְמֵילָד וְהָא תְיוּמִין בִּמְעָהָא:
@7 וּנְפַק קַדְמָאָה סִמוֹק כֻּלֵּהּ כִּגְלִים (נ''י כִּכְלָן) דִּשְׂעָר וּקְרוֹ שְׁמֵהּ עֵשָׂו:
@8 וּבָתַר כֵּן נְפַק אֲחוּהִי וִידֵהּ אֲחִידָא בְּעִקְבָא דְעֵשָׂו וּקְרָא שְׁמֵהּ יַעֲקֹב וְיִצְחָק בַּר שִׁתִּין שְׁנִין כַּד יְלִידַת יָתְהוֹן:
@9 וּרְבִיוּ עוּלֵמַיָּא וַהֲוָה עֵשָׂו גְבַר נַחְשִׁירְכָן גְבַר נָפֵק לְחַקְלָא וְיַעֲקֹב גְבַר שְׁלִים מְשַׁמֵשׁ בֵּית אוּלְפָנָא:
@10 וּרְחֵם יִצְחָק יָת עֵשָׂו אֲרֵי מִצֵידֵהּ הֲוָה אָכִיל וְרִבְקָה רְחִימַת יָת יַעֲקֹב:
@11 וּבַשִּׁיל יַעֲקֹב תַּבְשִׁילָא וַאֲתָא (נ'''י וְעַל) עֵשָׂו מִן חַקְלָא וְהוּא מְשַׁלְהֵי:
@12 וַאֲמַר עֵשָׂו לְיַעֲקֹב אַטְעֵמְנִי כְעַן מִן סִמּוֹקָא סִמּוֹקָא הָדֵין אֲרֵי מְשַׁלְהֵי אֲנָא עַל כֵּן קְרָא שְׁמֵהּ אֱדוֹם:
@13 וַאֲמַר יַעֲקֹב זַבִּין כְּיוֹם דִּלְהֵן יָת בְּכֵרוּתָךְ לִי:
@14 וַאֲמַר עֵשָׂו הָא אֲנָא אָזֵל לִמְמָת וּלְמָה דְּנָן לִי בְּכֵרוּתָא:
@15 וַאֲמַר יַעֲקֹב קַיֵּם לִי כְּיוֹם דִּלְהֵן וְקַיִּים לֵהּ וְזַבִּין יָת בְּכֵרוּתֵהּ לְיַעֲקֹב:
@16 וְיַעֲקֹב יְהַב לְעֵשָׂו לְחֵם וְתַבְשִׁיל דִּטְלוֹפְחִין וַאֲכַל וּשְׁתִי וְקָם וַאֲזָל וְשָׁט עֵשָׂו יָת בְּכֵרוּתָא:
@17 וַהֲוָה כַפְנָא בְּאַרְעָא בַּר מִכַּפְנָא קַדְמָאָה דִּי הֲוָה בְּיוֹמֵי אַבְרָהָם וַאֲזַל יִצְחָק לְוַת אֲבִימֶלֶךְ מַלְכָּא דִּפְלִשְׁתָּאֵי לִגְרָר:
@18 וְאִתְגְּלִי לֵהּ יְיָ וַאֲמַר לָא תֵחוֹת לְמִצְרָיִם שְׁרֵי בְאַרְעָא דִּי אֵימַר לָךְ:
@19 דּוּר בְּאַרְעָא הָדָא וִיהֵי מֵימְרִי בְסַעְדָךְ וְאֵבָרְכִנָךְ אֲרֵי לָךְ וְלִבְנָיךְ אֶתֵּן יָת כָּל אַרְעָתָא הָאִלֵּין וְאָקֵם יָת קְיָמָא דִּי קַיֵּמִית לְאַבְרָהָם אֲבוּךְ:
@20 וְאַסְגֵּי יָת בְּנָיךְ סַגִּיאִין כְּכוֹכְבֵי שְׁמַיָּא וְאֶתֵּן לִבְנָיךְ יָת כָּל אַרְעָתָא הָאִלֵּין וְיִתְבָּרְכוּן בְּדִיל בְּנָךְ כֹּל עַמְמֵי אַרְעָא:
@21 חֳלַף דִּי קַבִּיל אַבְרָהָם בְּמֵימְרִי וּנְטַר מַטְּרַת מֵימְרִי פִּקּוֹדַי קְיָמַי וְאוֹרָיָתָי:
@22 וִיתֵב יִצְחָק בִּגְרָר:
@23 וּשְׁאִילוּ אֲנָשֵׁי אַתְרָא (עַל עֵיסַק אִתְּתֵהּ) לְאִתְּתֵהּ וַאֲמַר אֲחָתִי הִיא אֲרֵי דְחִיל לְמֵימַר אִתְּתִי דִּלְמָא יִקְטְּלֻנַּנִי אֲנָשֵׁי אַתְרָא עַל רִבְקָה אֲרֵי שַׁפִּירַת חֵיזוּ הִיא:
@24 וַהֲוָה כַּד סְגִיאוּ לֵהּ תַּמָּן יוֹמַיָּא וְאִסְתְּכִי אֲבִימֶלֶךְ מַלְכָּא דִּפְלִשְׁתָּאֵי מִן חֲרַכָּא וַחֲזָא וְהָא יִצְחָק מְחַיִּיךְ עִם רִבְקָה אִתְּתֵהּ:
@25 וּקְרָא אֲבִימֶלֶךְ לְיִצְחָק וַאֲמַר בְּרַם הָא אִתְּתָךְ הִיא וְאֶכְדֵּין אֲמַרְתָּ אֲחָתִי הִיא וַאֲמַר לֵהּ יִצְחָק אֲרֵי אֲמָרִית דִּלְמָא אֵימוּת עֲלַהּ:
@26 וַאֲמַר אֲבִימֶלֶךְ מָה דָא עֲבַדְתָּ לָנָא כִּזְעֵיר פּוֹן שָׁכִיב דִּמְיָחֵד בְּעַמָּא עִם אִתְּתָךְ וְאַיְתֵיתָא עֲלָנָא חוֹבָא:
@27 וּפַקִּיד אֲבִימֶלֶךְ יָת כָּל עַמָּא לְמֵימָר דְּיַנְזֵק לְגַבְרָא הָדֵין וּבְאִתְּתֵהּ אִתְקְטָלָא יִתְקְטֵּל:
@28 וּזְרַע יִצְחָק בְּאַרְעָא הַהִיא וְאַשְׁכַּח בְּשַׁתָּא הַהִיא עַל חַד מְאָה בִדְשַׁעֲרוֹהִי וּבָרְכֵהּ יְיָ:
@29 וּרְבָא גַּבְרָא וַאֲזַל אֲזִיל (נ''י סָגֵי) וְרָבֵי עַד דִּי רְבָא לַחֲדָא:
@30 וַהֲוָה לֵהּ גֵּיתֵי עָנָא וְגֵיתֵי תוֹרִין וּפָלְחָנָא (נ''י וַעֲבוּדָה) סַגְיָא וְקַנִּיאוּ בֵהּ פְּלִשְׁתָּאֵי:
@31 וְכָל בֵּירִין דִּי חֲפָרוּ עַבְדֵי אֲבוּהִי בְּיוֹמֵי אַבְרָהָם אֲבוּהִי טַמּוֹנוּן פְּלִשְׁתָּאֵי וּמְלוֹנוּן עַפְרָא:
@32 וַאֲמַר אֲבִימֶלֶךְ לְיִצְחָק אִזְּל מֵעִמָּנָא אֲרֵי תְקֵפְתָּא מִנָּנָא לַחֲדָא:
@33 וַאֲזַל מִתַּמָּן יִצְחָק וּשְׁרָא בְנַחֲלָא דִּגְרָר וִיתֵב תַּמָּן:
@34 וְתָב יִצְחָק וְחָפַר יָת בֵּירֵי דְמַיָּא דִּי חֲפָרוּ בְּיוֹמֵי אַבְרָהָם אֲבוּהִי וְטַּמּוֹנוּן פְּלִשְׁתָּאֵי בָּתַר דְּמִית אַבְרָהָם וּקְרָא לְהֵן שְׁמָהָן כִּשְׁמָהָן דִּי הֲוָה קָרֵי לְהֵן אֲבוּהִי:
@35 וַחֲפָרוּ עַבְדֵי יִצְחָק בְּנַחֲלָא וְאַשְׁכָּחוּ תַמָּן בֵּירָא דְּמַיִּין נָבְעִין:
@36 וּנְצוֹ רַעֲוָתָא דִּגְרָר עִם רַעֲוָתָא דְיִצְחָק לְמֵימַר דִּי לָנָא מַיָּא וּקְרָא שְׁמָא דְבֵירָא עִסְקָא אֲרֵי אִתְעַסִּיקוּ עִמֵּהּ:
@37 וַחֲפָרוּ בֵּירָא אָחֳרִי וּנְצוֹ אַף עֲלַהּ וּקְרָא שְׁמַהּ שִׂטְנָא:
@38 וְאִסְתַּלַּק מִתַּמָּן וַחֲפַר בֵּירָא אָחֳרִי וְלָא נְצוֹ עֲלַהּ וּקְרָא שְׁמַהּ רְחֹבוֹת וַאֲמַר אֲרֵי כְעַן אַפְתֵּי יְיָ לָנָא וְנִיפוּשׁ בְּאַרְעָא:
@39 וְאִסְתַּלַּק מִתַּמָּן לִבְּאֵר שָׁבַע:
@40 וְאִתְגְּלִי לֵהּ יְיָ בְּלֵילְיָא הַהוּא וַאֲמַר אֲנָא אֱלָהֵהּ דְּאַבְרָהָם אֲבוּךְ לָא תִדְחַל אֲרֵי בְסַעְדָּךְ מֵימְרִי וֶאֱבָרֵכִנָּךְ וְאַסְגֵּי יָת בְּנָיךְ בְּדִיל אַבְרָהָם עַבְדִּי:
@41 וּבְנָא תַמָּן מַדְבְּחָא וְצַלִּי בִּשְׁמָא דַּיְיָ וּפְרַס תַּמָּן מַשְׁכְּנֵהּ וּכְרוֹ תַמָּן עַבְדֵי יִצְחָק בֵּירָא:
@42 וַאֲבִימֶלֶךְ אֲזַל לְוָתֵהּ מִגְּרָר וְסִיעַת מֵרַחֲמוֹהִי וּפִיכֹל רַב חֵילֵהּ:
@43 וַאֲמַר לְהוֹן יִצְחָק מָה דֵּין אֲתֵיתוּן לְוָתִי וְאַתּוּן סְנֵיתוּן יָתִי וְשַׁלַּחְתּוּנִי מִלְּוָתְכוֹן:
@44 וַאֲמָרוּ מֶחֱזָא חֲזֵינָא אֲרֵי הֲוָה מֵימְרָא דַּיְיָ בִּסַעְדָּךְ וַאֲמַרְנָא תִּתְקַיַּם כְּעַן מוֹמָתָא דִּהֲוָה בֵין אֲבָהָתָנָא בֵּינָנָא וּבֵינָךְ וְנִגְזַר קְיָם עִמָּךְ:
@45 אִם תַּעְבֵּד עִמָּנָא בִּישָׁא כְּמָא דִּי לָא אַנְזִיקְנָךְ וּכְמָא דִּי עֲבַדְנָא עִמָךְ לְחוֹד טָב וַנְשַׁלְּחִנָּךְ בִּשְׁלָם אַתְּ כְּעַן בְּרִיכָא דַּיְיָ:
@46 וַעֲבַד לְהוֹן מִשְׁתְּיָא וַאֲכָלוּ וּשְׁתִיאוּ:
@47 וְאַקְדִימוּ בְצַפְרָא וְקַיִּימוּ גְּבַר לְאָחוּהִי וְשַׁלָּחִנוּן יִצְחָק וַאֲזָלוּ מִלְוָתֵהּ בִּשְׁלָם:
@48 וַהֲוָה בְּיוֹמָא הַהוּא וַאֲתוֹ עַבְדֵי יִצְחָק וְחַוִּיאוּ לֵהּ עַל עֵיסַק בֵּירָא דִּי חֲפָרוּ וַאֲמָרוּ לֵהּ אַשְׁכַּחְנָא מַיָּא:
@49 וּקְרָא יָתַהּ שִׁבְעָה עַל כֵּן שְׁמָא דְקַרְתָּא בְּאֵרָא דְשֶׁבַע (נ''י בְּאֵר שֶׁבַע) עַד יוֹמָא הָדֵין:
@50 וַהֲוָה עֵשָׂו בַּר אַרְבְּעִין שְׁנִין וּנְסִיב אִתְּתָא יָת יְהוּדִית בַּת בְּאֵרִי חִתָּאָה וְיָת בָּשְׂמַת בַּת אֵילוֹן חִתָּאָה:
@51 וַהֲוָאָה מְסָרְבָן וּמְרַגְּזָן עַל מֵימַר יִצְחָק וְרִבְקָה:
@52 וַהֲוָה כַּד סִיב יִצְחָק וְכָהֲיָּא עֵינוֹהִי מִלְּמֶחֱזֵי וּקְרָא יַת עֵשָׂו בְּרֵהּ רַבָּה וַאֲמַר לֵהּ בְּרִי וַאֲמַר לֵהּ הָא אָנָא:
@53 וַאֲמַר הָא כְעַן סֵיבִית לֵית אֲנָא יְדַע יוֹמָא דְאֵימוּת:
@54 וּכְעַן סַב כְּעַן זֵינָךְ סַיְפָךְ וְקַשְׁתָּךְ וּפוּק לְחַקְלָא וְצוּד לִי צֵידָא:
@55 וְעִבֵיד לִי תַבְשִׁילִין כְּמָא דִרְחֵימִית וְאָעֵל לִי וְאֵיכוּל בְּדִיל דִּי תְבָרֵכִנָּךְ נַפְשִׁי עַד לָא אֵימוּת:
@56 וְרִבְקָה שְׁמַעַת כַּד מַלִּיל יִצְחָק לְוַת עֵשָׂו בְּרֵהּ וַאֲזַל עֵשָׂו לְחַקְלָא לְמֵיצַד צֵידָא לְאַיְתָאָה:
@57 וְרִבְקָה אֲמָרַת לְוַת יַעֲקֹב בְּרַהּ לְמֵימָר הָא שְׁמָעִית יַת אֲבוּךְ מְמַלֵּל עִם עֵשָׂו:אַחוּךְ לְמֵימָר:
@58 אַיְתִי לִי צֵידָא וְעִבֵּיד לִי תַבְשִׁילִין וְאֵיכוּל וֶאֱבָרֵכִנָּךְ קֳדָם יְיָ קֳדָם מוֹתִי:
@59 וּכְעַן בְּרִי קַבֵּל מִנִי לְמָא דִי אֲנָא:מפַקֵד יָתָךְ:
@60 אִזֵיל כְּעַן לְוַת עָנָא וְסַב לִי מִתַּמָּן תְּרֵין גַדְיֵי (בַר) עִזְּין טָבָן וְאֶעְבֵּד יָתְהוֹן תַּבְשִׁילִין לְאָבוּךְ כְּמָא דִי רְחֵם:
@61 וְתַיְתִי (נ''י וְתָעֵל) לְאָבוּךְ וְיֵכוּל בְּדִיל דִּיְבָרְכִנָּךְ קֳדָם מוֹתֵהּ:
@62 וַאֲמַר יַעֲקֹב לְרִבְקָה אִמֵּהּ הָא עֵשָׂו אָחִי גְּבַר שַׂעֲרָן וַאֲנָא גְּבַר שְׁעִיעַ:
@63 מָאִים יְמֻשִּׁנַּנִי אַבָּא וְאֵהֵי בְעֵינוֹהִי כְּמִתְלָעָב וְאֵהֵי מַיְתֵי (נ''י וָאֱהִי מַיְתֵי) עֲלַי לְוָטִין וְלָא בִרְכָן:
@64 וַאֲמֶרֶת לֵהּ אִמֵּהּ עֲלַי אִתְאַמַּר בִּנְבוּאָה דְּלָא יֵיתוּן לְוָטַּיָּא עֲלָךְ בְּרִי בְּרַם קַבֵּל מִנִּי וְאִזְּיל סַב לִי:
@65 וַאֲזַל וּנְסִיב וְאַיְתִי לְאִמֵּהּ וַעֲבָדַת אִמֵּהּ תַּבְשִׁילִין כְּמָא דִּרְחֵם אֲבוּהִי:
@66 וּנְסִיבַת רִבְקָה יָת לְבוּשֵׁי עֵשָׂו בְּרַהּ רַבָּא דָּכְיָתָא דִּי עִמַּהּ בְּבֵיתָא וְאַלְבִּישַׁת יָת יַעֲקֹב בְּרַהּ זְעֵירָא:
@67 וְיָת מַשְׁכֵי גַּדְיֵי בַּר עִזֵּי אַלְבִּישַׁת עַל יְדוֹהִי וְעַל שְׁעִיעוּת צַוְרֵהּ:
@68 וִיהָבַת יָת תַּבְשִׁילַיָּא וְיָת לַחְמָא דִּי עֲבָדַת בִּידָא דְיַעֲקֹב בְּרַהּ:
@69 וְעַל לְוַת אֲבוּהִי וַאֲמַר אַבָּא וַאֲמַר הָא אֲנָא מָן אַתְּ בְּרִי:
@70 וַאֲמַר יַעֲקֹב לַאֲבוּהִי אֲנָא עֵשָׂו בּוּכְרָךְ עֲבָדִית כּמָא דִי מַלֵּילְתָּא עִמִּי (נ''י:לִי) קוּם כְּעַן אִסְתַּחַר וֶאֱכוּל מִצֵידִי בְּדִיל דִּי תבָרכִנַּנִּי נַפְשָׁךְ:
@71 וַאֲמַר יִצְחָק לִבְרֵהּ מָה דֵּין אוֹחֵיתָא לְאַשְׁכָּחָא בְּרִי וַאֲמַר אֲרֵי זַמִּין יְיָ אֱלָהָךְ קֳדָמַי:
@72 וַאֲמַר יִצְחָק לְיַעֲקֹב קְרֵיב כְּעַן וֶאֱמֻשִּׁנָּךְ בְּרִי הַאַתְּ דֵּין בְּרִי עֵשָׂו אִם לָא:
@73 וּקְרֵיב יַעֲקֹב לְוַת יִצְחָק אֲבוּהִי וּמָשְׁיֵהּ וַאֲמַר קָלָא קָלָא דְיַעֲקֹב וִידַיָּא יְדוֹהִי דְעֵשָׂו:
@74 וְלָא אִשְׁתְּמוֹדְעֵהּ אֲרֵי הֲוָאָה יְדוֹהִי כִּידֵי עֵשָׂו אֲחוּהִי שְׂעִירָן (נ''י שַׂעֲרַנְיָן) וּבָרְכֵהּ:
@75 וַאֲמַר אַתְּ דֵּין בְּרִי עֵשָׂו וַאֲמַר הָא אֲנָא:
@76 וַאֲמַר קָרֵיב קֳדָמַי וְאֵיכוּל מִצֵידָא דִּבְרִי בְּדִיל דִּי תְבָרְכִנָּךְ נַפְשִׁי וְקָרֵיב לֵהּ וַאֲכַל וְאַיְתִי (נ''י וְאָעֵל) לֵהּ חַמְרָא וּשְׁתִי:
@77 וַאֲמַר לֵהּ יִצְחָק אֲבוּהִי קְרֵיב כְּעַן וּנְשַׁק לִי (נ''י וְשַׁק לִי) בְּרִי:
@78 וּקְרֵב וּנְשַׁק לֵהּ וַאֲרַח יָת רֵיחָא דִּלְבוּשׁוֹהִי וּבָרְכֵהּ וַאֲמַר חֲזֵי רֵיחָא דִּבְרִי כְּרֵיחָא דְחַקְלָא דִּי בָרֲכֵהּ יְיָ:
@79 וְיִתֶּן לָךְ יְיָ מִטַּלָּא דִּשְׁמַיָּא וּמִטּוּבָא דְאַרְעָא וּסְגִיאוּת (נ''י וְסַגְיוּת) עִיבוּר וַחֲמָר:
@80 יִפְלְחֻנָּךְ עַמְמִין וְיִשְׁתַּעְבְּדוּן לָךְ מַלְכְּוָן הֱוֵי רַב לְאַחָיךְ וְיִסְגְּדוּן לָךְ בְּנֵי אִמָּךְ מְלַטְטָיךְ יְהוֹן לִיטִין וּמְבָרֲכָיךְ יְהוֹן בְּרִיכִין:
@81 וַהֲוָה כַּד שֵׁיצֵי יִצְחָק לְבָרָכָא יָת יַעֲקֹב וַהֲוָה בְּרַם מִפַּק נְפַק יַעֲקֹב מִלְּוַת אַפֵּי יִצְחָק אֲבוּהִי וְעֵשָׂו אֲחוּהִי אָתָא (נ''י עַל) מִצֵידֵהּ:
@82 וַעֲבַד אַף הוּא תַּבְשִׁילִין וְאָעֵיל לְוַת אֲבוּהִי וַאֲמַר לַאֲבוּהִי יָקוּם אַבָּא וְיֵכוּל מִצֵידָא דִּבְרֵהּ בְּדִיל דִּי תְבָרְכִנַּנִּי נַפְשָׁךְ:
@83 וַאֲמַר לֵהּ יִצְחָק אֲבוּהִי מָן אָתְּ וַאֲמַר אֲנָא בְּרָךְ בּוּכְרָךְ עֵשָׂו:
@84 וּתְוָה יִצְחָק תִּוְהָא רַבָּא עַד לַחֲדָא וַאֲמַר מָן הוּא דֵּיכִי דְצָד צֵידָא וְאָעֵיל לִי וַאֲכָלִית מִכֹּלָּא עַד לָא תֵיעוֹל וּבָרֵכִתֵּהּ אַף בְּרִיךְ יְהֵי:
@85 כַּד שְׁמַע עֵשָׂו יָת פִּתְגָּמֵי אֲבוּהִי וּצְוַח צִוְחָא רַבָּא וּמְרִירָא עַד לַחֲדָא וַאֲמַר לַאֲבוּהִי בָּרֵכְנִי אַף אֲנָא (נ''י לִי) אַבָּא:
@86 וַאֲמַר עַל אָחוּךְ בְּחָכְמְתָא וְקַבִּיל בִּרְכְּתָךְ:
@87 וַאֲמַר יָאוּת קְרָא שְׁמֵהּ יַעֲקֹב וְכָמַנִי דְּנָן תַּרְתֵּין זִמְנִין יָת בְּכֵירוּתִי נְסִיב וְהָא כְּעַן קַבִּיל בִּרְכְּתִי וַאֲמַר הֲלָא שְׁבַקְתָּ לִי בִּרְכְּתָא:
@88 וַאֲתֵיב יִצְחָק וַאֲמַר לְעֵשָׂו הָא רַב שַׁוִּתֵּהּ לָךְ (נ''י עִלַּוָּךְ) וְיָת כָּל אֲחוֹהִי יְהָבִית לֵהּ לְעַבְדִּין וְעִיבוּר וַחֲמָר סְעִדְתֵּהּ וְלָךְ הָכָא מָה אֶעְבֵּיד בְּרִי:
@89 וַאֲמַר עֵשָׂו לַאֲבוּהִי הֲבִרְכְּתָא חֲדָא הִיא לָךְ אַבָּא בָּרֵךְ לִי אַף אֲנָא אַבָּא וַאֲרֵים עֵשָׂו קָלֵהּ וּבְכָא:
@90 וַאֲתֵיב יִצְחָק אֲבוּהִי וַאֲמַר לֵהּ הָא מִטּוּבָא דְאַרְעָא יְהֵא מוֹתְבָךְ וּמִטַּלָּא דִּשְׁמַיָּא מִלְּעֵלָא:
@91 וְעַל חַרְבָּךְ תֵּיחֵי וְיָת אָחוּךְ תִּפְלָח וִיהֵי כַּד יַעְבְּרוּן בְּנוֹהִי עַל פִּתְגָּמֵי אוֹרַיְתָא וְתַעְדִּי נִירֵהּ מֵעַל צַוְרָךְ:
@92 וּנְטַר עֵשָׂו דְּבָבוּ לְיַעֲקֹב עַל בִּרְכְּתָא דִּי בָרְכֵהּ אֲבוּהִי וַאֲמַר עֵשָׂו בְּלִבֵּהּ יִקְרְבוּן יוֹמֵי אֶבְלֵי דְאַבָּא וְאֶקְטוֹל יָת יַעֲקֹב אָחִי:
@93 וְאִתְחַוָּה לְרִבְקָה יָת פִּתְגָּמֵי עֵשָׂו בְּרַהּ רַבָּא וּשְׁלָחַת וּקְרַת לְיַעֲקֹב בְּרַהּ זְעֵירָא וַאֲמֶרֶת לֵהּ הָא עֵשָׂו אָחוּךְ כָּמִן לָךְ לְמִקְטְלָךְ:
@94 וּכְעַן בְּרִי קַבֵּל מִנִּי וְקוּם אִזֵּיל לָךְ לְוַת לָבָן אָחִי לְחָרָן:
@95 וְתֵתֵיב עִמֵּהּ יוֹמִין זְעֵירִין עַד דִּיתוּב רוּגְזָא דְאָחוּךְ:
@96 עַד דִּיתוּב רוּגְזָא דְאָחוּךְ מִנָּךְ וְיִתְנְשֵׁי יָת דִּי עֲבַדְתָּ לֵהּ וְאֶשְׁלַח וְאֶדְבְּרִנָּךְ מִתַּמָּן לְמָה אֶתְכַּל אַף תַּרְוֵיכוֹן יוֹמָא חָד:
@97 וַאֲמֶרֶת רִבְקָה לְיִצְחָק עָקִית בְּחַיַּי מִן קֳדָם בְּנַת חִתָּאָה אִם נְסִיב יַעֲקֹב אִתְּתָא מִבְּנַת חִתָּאָה כְאִלֵּין מִבְּנַת אַרְעָא לְמָה לִי חַיִּים:
@98 וּקְרָא יִצְחָק לְיַעֲקֹב וּבָרִיךְ יָתֵהּ וּפַקְדֵהּ וַאֲמַר לֵהּ לָא תִסַּב אִתְּתָא מִבְּנַת כְּנָעַן:
@99 קוּם אִזֵּיל לְפַדַּן אֲרָם לְבֵית בְּתוּאֵל אֲבוּהָא דְאִמָּךְ וְסַב לָךְ מִתַּמָּן אִתְּתָא מִבְּנַת לָבָן אֲחוּהָא דְאִמָּךְ:
@100 וְאֵל שַׁדַּי יְבָרֵךְ יָתָךְ וְיַפְּשָׁךְ וְיַסְגִּנָּךְ וּתְהֵי לְכִנְשַׁת שִׁבְטִין:
@101 וְיִתֶּן לָךְ יָת בִּרְכְּתָא דְאַבְרָהָם לָךְ וְלִבְנָיךְ עִמָּךְ לְמֵירְתָךְ יָת אֲרַע תּוֹתָבוּתָךְ דִּי יְהַב יְיָ לְאַבְרָהָם:
@102 וּשְׁלַח יִצְחָק יָת יַעֲקֹב וַאֲזַל לְפַדַּן אֲרָם לְוַת לָבָן בַּר בְּתוּאֵל אֲרַמָּאָה אֲחוּהָא דְרִבְקָה אִמֵּהּ דְּיַעֲקֹב וְעֵשָׂו:
@103 וַחֲזָא עֵשָׂו אֲרֵי בָרִיךְ יִצְחָק יָת יַעֲקֹב וְשַׁלַּח יָתֵהּ לְפַדַּן אֲרָם לְמִסַּב לֵהּ מִתַּמָּן אִתְּתָא כַּד בָּרִיךְ יָתֵהּ וּפַקֵּיד עֲלוֹהִי לְמֵימַר לָא תִסַּב אִתְּתָא מִבְּנַת כְּנָעַן:
@104 וְקַבִּיל יַעֲקֹב מִן אֲבוּהִי וּמִן אִמֵּהּ וַאֲזַל לְפַדַּן אֲרָם:
@105 וַחֲזָא עֵשָׂו אֲרֵי בִישָׁא בְּנַת כְּנָעַן בְּעֵינֵי יִצְחָק אֲבוּהִי:
@106 וַאֲזַל עֵשָׂו לְוַת יִשְׁמָעֵאל וּנְסִיב יָת מַחֲלַת בַּת יִשְׁמָעֵאל בַּר אַבְרָהָם אֲחָתֵהּ דִּנְבָיוֹת עַל נְשׁוֹהִי לֵהּ לְאִנְתּוּ: ססס:

@1 **ואלה תולדות יצחק.** יעקב ועשו האמורים בפרשה: **אברהם הוליד את יצחק.** על ידי שכתב הכתוב יצחק בן אברהם הזקק לומר אברהם הוליד את יצחק, לפי שהיו ליצני הדור אומרים מאבימלך נתעברה שרה, שהרי כמה שנים שהתה עם אברהם ולא נתעברה המנו, מה עשה הקדוש ברוך הוא, צר קלסתר פניו של יצחק דומה לאברהם, והעידו הכל אברהם הוליד את יצחק, וזהו שכתב כאן יצחק בן אברהם היה, שהרי עדות יש שאברהם הוליד את יצחק:
@2 **בן ארבעים שנה.** שהרי כשבא אברהם מהר המוריה נתבשר שנלדה רבקה, ויצחק היה בן שלשים ושבע שנה, שהרי בו בפרק מתה שרה, ומשנלד יצחק עד העקידה שמתה שרה שלשים ושבע שנה, ובת תשעים היתה כשנלד יצחק, ובת מאה עשרים ושבע כשמתה, שנאמר (כג א) ויהיו חיי שרה וגו' , הרי ליצחק שלשים ושבע שנים ובו בפרק נלדה רבקה, המתין לה עד שתהא ראויה לביאה שלש שנים ונשאה: **בת בתואל מפדן ארם אחות לבן.** וכי עדיין לא נכתב שהיא בת בתואל ואחות לבן ומפדן ארם, אלא להגיד שבחה שהיתה בת רשע ואחות רשע ומקומה אנשי רשע, ולא למדה ממעשיהם: **מפדן ארם.** על שם ששני ארם היו, ארם נהרים וארם צובה, קורא אותו פדן, לשון (שמואל א' יא ז) צמד בקר, תרגום פדן תורין. ויש פותרין פדן ארם כמו (הושע יב יג) שדה ארם, שבלשון ישמעאל קורין לשדה פדן:
@3 **ויעתר.** הרבה והפציר בתפלה: **ויעתר לו.** נתפצר ונתפייס ונתפתה לו, ואומר אני כל לשון עתר לשון הפצרה ורבוי הוא וכן (יחזקאל ח יא) ועתר ענן הקטרת, מרבית עלית העשן, וכן (שם לה יג) והעתרתם עלי דבריכם, וכן (משלי כז ו) נעתרות נשיקות שונא, דומות למרבות והנם למשא. אינקריישימינ''ט בלע''ז : **לנכח אשתו.** זה עומד בזוית זו ומתפלל, וזו עומדת בזוית זו ומתפללת: **ויעתר לו.** לו ולא לה, שאין דומה תפלת צדיק בן צדיק לתפלת צדיק בן רשע לפיכך לו ולא לה:
@4 **ויתרוצצו.** על כרחך המקרא הזה אומר דרשני, שסתם מה היא רציצה זו וכתב אם כן למה זה אנכי. רבותינו דרשוהו לשון ריצה, כשהיתה עוברת על פתחי תורה של שם ועבר יעקב רץ ומפרכס לצאת, עוברת על פתחי עבודה זרה עשו מפרכס לצאת. דבר אחר מתרוצצים זה עם זה ומריבים בנחלת שני עולמות: **ותאמר אם כן.** גדול צער העבור: **למה זה אנכי.** מתאוה ומתפללת על הריון: **ותלך לדרש.** לבית מדרשו של שם: **לדרש את ה'.** שיגיד לה מה תהא בסופה:
@5 **ויאמר ה' לה.** על ידי שליח, לשם נאמר ברוח הקודש והוא אמר לה: **שני גוים בבטנך.** גיים כתיב, אלו אנטונינוס ורבי, שלא פסקו מעל שלחנם לא צנון ולא חזרת לא בימות החמה ולא בימות הגשמים: **ושני לאמים.** אין לאום אלא מלכות: **ממעיך יפרדו.** מן המעים הם נפרדים, זה לרשעו וזה לתמו: **מלאם יאמץ.** לא ישוו בגדולה, כשזה קם זה נופל, וכן הוא אומר (יחזקאל כו ב) אמלאה החרבה, לא נתמלאה צור אלא מחרבנה של ירושלים:
@6 **וימלאו ימיה.** אבל בתמר כתיב (להלן לח כז) ויהי בעת לדתה. שלא מלאו ימיה כי לשבעה חדשים ילדתם: **והנה תומם.** חסר, ובתמר תאומים מלא לפי ששניהם צדיקים, אבל כאן אחד צדיק ואחד רשע:
@7 **אדמוני.** סימן הוא שיהא שופך דמים: **כלו כאדרת שער.** מלא שער כטלית של צמר המלאה שער פלוקייד''א בלע''ז : **ויקראו שמו עשו.** הכל קראו לו כן, לפי שהיה נעשה ונגמר בשערו כבן שנים הרבה:
@8 **ואחרי כן יצא אחיו** וגו' **.** שמעתי מדרש אגדה הדורשו לפי פשוטו, בדין היה אוחז בו לעכבו, יעקב נצר מטפה ראשונה ועשו מן השניה, צא ולמד משפופרת שפיה קצרה, תן לה שתי אבנים זו תחת זו, הנכנסת ראשונה תצא אחרונה, והנכנסת אחרונה תצא ראשונה, נמצא עשו הנצר באחרונה יצא ראשון, ויעקב שנצר ראשונה יצא אחרון, ויעקב בא לעכבו שיהא ראשון ללידה כראשון ליצירה, ויפטור את רחמה, ויטול את הבכורה מן הדין: **בעקב עשו.** סימן שאין זה מספיק לגמור מלכותו עד שזה עומד ונוטלה המנו: **ויקרא שמו יעקב.** הקדוש ברוך הוא. דבר אחר אביו קרא לו יעקב על שם אחיזת העקב: **בן ששים שנה.** עשר שנים משנשאה עד שנעשית בת שלש עשרה שנה וראויה להריון ועשר שנים הללו צפה והמתין לה כמו שעשה אביו לשרה, כיון שלא נתעברה ידע שהיא עקרה והתפלל עליה. ושפחה לא רצה לשא, לפי שנתקדש בהר המוריה להיות עולה תמימה:
@9 **ויגדלו הנערים ויהי עשו.** כל זמן שהיו קטנים לא היו נכרים במעשיהם ואין אדם מדקדק בהם מה טיבם, כיון שנעשו בני שלש עשרה שנה זה פרש לבתי מדרשות וזה פרש לעבודה זרה: **ידע ציד.** לצוד ולרמות את אביו בפיו, ושואלו אבא היאך מעשרין את המלח ואת התבן, כסבור אביו שהוא מדקדק במצות: **איש שדה.** כמשמעו אדם בטל וצודה בקשתו חיות ועופות: **תם.** אינו בקי בכל אלה, אלא כלבו כן פיו. מי שאינו חריף לרמות קרוי תם: **ישב אהלים.** אהלו של שם ואהלו של עבר:
@10 **בפיו.** כתרגומו בפיו של יצחק. ומדרשו בפיו של עשו שהיה צד אותו ומרמהו בדבריו:
@11 **ויזד.** לשון בשול, כתרגומו: **והוא עיף.** ברציחה, כמה דתימא (ירמיה ד לא) כי עיפה נפשי להורגים:
@12 **הלעיטני.** אפתח פי ושפוך הרבה לתוכו, כמו ששנינו: אין אובסין את הגמל אבל מלעיטין אותו (שבת קנה:) : **מן האדם האדם.** עדשים אדמות, ואותו היום מת אברהם שלא יראה את עשו בן בנו יוצא לתרבות רעה, ואין זו שיבה טובה שהבטיחו הקדוש ברוך הוא, לפיכך קצר הקדוש ברוך הוא חמש שנים משנותיו, שיצחק חי מאה ושמונים שנה וזה מאה שבעים וחמש שנה, ובשל יעקב עדשים להברות את האבל. ולמה עדשים, שדומות לגלגל שהאבלות גלגל החוזר בעולם (ועוד מה עדשים אין להם פה כך האבל אין לו פה שאסור לדבר. לפיכך המנהג להברות את האבל בתחלת מאכלו ביצים שהם עגלים ואין להם פה, כך אבל אין לו פה כדאמרינן במועד קטן (כא ב) אבל כל שלשה ימים הראשונים אינו משיב שלום לכל אדם וכל שכן שאינו שואל בתחלה, משלשה ועד שבעה משיב ואינו שואל וכו' ) :
@13 **מכרה כיום.** כתרגומו, כיום דילהן, כיום שהוא ברור, כך מכור לי מכירה ברורה: **בכרתך.** לפי שהעבודה בבכורות, אמר יעקב אין רשע זה כדאי שיקריב להקדוש ברוך הוא:
@14 **הנה אנכי הולך למות.** (מתנודדת והולכת היא הבכורה שלא תהא כל עת העבודה בבכורות כי שבט לוי יטל אותה ועוד) אמר עשו מה טיבה של עבודה זו, אמר לו כמה אזהרות וענשין ומיתות תלוין בה, כאותה ששנינו אלו הן שבמיתה שתויי יין, ופרועי ראש. אמר אני הולך למות על ידה, אם כן מה חפץ לי בה:
@16 **ויבז עשו.** העיד הכתוב על רשעו שבזה עבודתו של מקום:
@18 **אל תרד מצרימה.** שהיה דעתו לרדת מצרימה כמו שירד אביו בימי הרעב, אמר לו אל תרד מצרימה שאתה עולה תמימה, ואין חוצה לארץ כדאי לך:
@19 **האל.** כמו האלה:
@20 **והתברכו בזרעך.** אדם אומר לבנו יהא זרעך כזרעו של יצחק, וכן בכל המקרא. וזה אב לכלן (להלן מח כ) בך יברך ישראל לאמר ישימך אלהים כאפרים וכמנשה, ואף לענין הקללה מצינו כן (במדבר ה כז) והיתה האשה לאלה, שהמקלל שונאו אומר תהא כפלונית, וכן (ישעיה סה טו) והנחתם שמכם לשבועה לבחירי, שהנשבע אומר אהא כפלוני אם עשיתי כך וכך:
@21 **שמע אברהם בקלי.** כשנסיתי אותו: **וישמר משמרתי.** גזרות להרחקה על אזהרות שבתורה, כגון שניות לעריות ושבות לשבת: **מצותי.** דברים שאלו לא נכתבו ראויין הם להצטוות כגון גזל ושפיכות דמים: **חקותי.** דברים שיצר הרע ואמות העולם משיבין עליהן כגון אכילת חזיר ולבישת שעטנז שאין טעם בדבר אלא גזרת המלך וחקותיו על עבדיו: **ותורתי.** להביא תורה שבעל פה, הלכה למשה מסיני:
@23 **לאשתו.** על אשתו, כמו (לעיל כ יג) אמרי לי אחי הוא:
@24 **כי ארכו.** אמר מעתה אין לי לדאוג מאחר שלא אנסוה עד עכשיו, ולא נזהר להיות נשמר: **וישקף אבימלך** וגו' **.** שראהו משמש מטתו:
@26 **אחד העם.** המיחד בעם זה המלך: **והבאת עלינו אשם.** אם שכב, כבר הבאת עלינו אשם:
@28 **בארץ ההיא.** אף על פי שאינה חשובה כארץ ישראל עצמה, כארץ שבעה גוים: **בשנה ההיא.** אף על פי שאינה כתקנה, שהיתה שנת רעבון: **בארץ ההיא בשנה ההיא.** שניהם למה, לומר שהארץ קשה והשנה קשה: **מאה שערים.** שאמדוה כמה ראויה לעשות ועשתה על אחת מאה ממה שאמדוה. ורבותינו אמרו אומד זה למעשרות היה:
@29 **כי גדל מאד.** שהיו אומרים זבל פרדותיו של יצחק ולא כספו וזהבו של אבימלך:
@30 **ועבדה רבה.** פעלה רבה, בלשון לע''ז אובריינ''א [מכלול העבודות] עבודה משמע עבודה אחת, עבדה משמע פעלה רבה:
@31 **סתמום פלשתים.** מפני שאמרו תקלה הם לנו מפני הגיסות הבאות עלינו. טמונין פלשתאי לשון סתימה, ובלשון משנה (פסחים מב א) מטמטם את הלב:
@33 **בנחל גרר.** רחוק מן העיר:
@34 **וישב ויחפר.** הבארות אשר חפרו בימי אברהם אביו. ופלשתים סתמום, מקדם שנסע יצחק מגרר חזר וחפרן:
@36 **עשק.** ערעור: **כי התעשקו עמו.** נתעשקו עמו עליה במריבה וערעור:
@37 **שטנה.** נוישימונ''ט [נזק]:
@38 **ופרינו בארץ.** כתרגומו ונפוש בארעא:
@42 **ואחזת מרעהו.** כתרגומו וסיעת מרחמוהי, סיעת מאוהביו. ויש פותרין מרעהו מ' מיסוד התבה, כמו (שופטים יד יא) שלשים מרעים דשמשון, כדי שתהיה תבת ואחזת דבוקה, אבל אין דרך ארץ לדבר על המלכות כן סיעת אוהביו, שאם כן כל סיעת אוהביו הוליך עמו ולא היה לו אלא סיעה אחת של אוהבים, לכן יש לפתרו כלשון הראשון. ואל תתמה על תי''ו של ואחזת ואף על פי שאין התבה סמוכה, יש דגמתה במקרא (תהלים ס יג) עזרת מצר, (ישעיה נא כא) ושכורת ולא מיין: **אחזת.** לשון קבוצה ואגודה שנאחזין יחד:
@44 **ראו ראינו.** ראה באביך ראינו בך: **תהי נא אלה בינותינו** וגו' **.** האלה אשר בינותינו מימי אביך, תהי גם עתה בינינו וביניך:
@45 **לא נגענוך.** כשאמרנו (לעיל פסוק טז) לך מעמנו: **אתה.** גם אתה עשה עמנו כמו כן:
@49 **שבעה.** על שם הברית:
@50 **בן ארבעים שנה.** עשו היה נמשל לחזיר, שנאמר (תהלים פ יד) יכרסמנה חזיר מיער, החזיר הזה כשהוא שוכב פושט טלפיו לומר ראו שאני טהור, כך אלו [אלופי עשו] גוזלים וחומסים ומראים עצמם כשרים. כל ארבעים שנה היה עשו צד נשים מתחת בעליהן ומענה אותם, כשהיה בן ארבעים אמר אבא בן ארבעים שנה נשא אשה, אף אני כן:
@51 **מרת רוח.** לשון המראות רוח, כמו (דברים ט כד) ממרים הייתם כל מעשיהן היו לעצבון: **ליצחק ולרבקה.** שהיו עובדות עבודה זרה:
@52 **ותכהין.** בעשנן של אלו. דבר אחר כשנעקד על גבי המזבח והיה אביו רוצה לשחטו, באותה שעה נפתחו השמים וראו מלאכי השרת והיו בוכים וירדו דמעותיהם ונפלו על עיניו, לפיכך כהו עיניו. דבר אחר כדי שיטול יעקב את הברכות:
@53 **לא ידעתי יום מותי.** אמר רבי יהושע בן קרחה, אם מגיע אדם לפרק אבותיו ידאג חמש שנים לפניהם וחמש לאחר כן, ויצחק היה בן מאה עשרים ושלש, אמר שמא לפרק אמי אני מגיע, והיא מתה בת מאה עשרים ושבע והריני בן חמש שנים סמוך לפרקה, לפיכך לא ידעתי יום מותי, שמא לפרק אמי, שמא לפרק אבא:
@54 **תליך.** חרבך שדרך לתלותה: **שא נא.** לשון השחזה כאותה ששנינו (ביצה כח א) אין משחיזין את הסכין אבל משיאה על גבי חברתה, חדד סכינך ושחוט יפה, שלא תאכילני נבלה: **וצודה לי.** מן ההפקר ולא מן הגזל:
@56 **לצוד ציד להביא.** מהו להביא, אם לא ימצא ציד יביא מן הגזל:
@58 **לפני ה'.** ברשותו שיסכים על ידי:
@60 **וקח לי.** משלי הם ואינם גזל, שכך כתב לה יצחק בכתבתה לטול שני גדיי עזים בכל יום: **שני גדיי עזים.** וכי שני גדיי עזים היה מאכלו של יצחק, אלא האחד הקריב לפסחו והאחד עשה מטעמים. בפרקי דרבי אליעזר (פרק לב) : **כאשר אהב.** כי טעם הגדי כטעם הצבי:
@62 **איש שער.** בעל שער:
@63 **ימשני.** כמו (דברים כח כט) ממשש בצהרים:
@66 **החמודות.** הנקיות, כתרגומו דכייתא. דבר אחר שחמד אותן מן נמרוד: **אשר אתה בבית.** והלא כמה נשים היו לו והוא מפקיד אצל אמו, אלא שהיה בקי במעשיהן וחושדן:
@70 **אנכי עשו בכרך.** אנכי המביא לך, ועשו הוא בכרך: **עשיתי.** כמה דברים כאשר דברת אלי: **שבה.** לשון מיסב על השלחן, לכך מתורגם אסתחר:
@72 **גשה נא ואמשך.** אמר יצחק בלבו אין דרך עשו להיות שם שמים שגור בפיו, וזה אמר (פסוק כ) כי הקרה ה' אלהיך:
@73 **קול יעקב.** שמדבר בלשון תחנונים (פסוק יט) קום נא, אבל עשו בלשון קנטוריא דבר (פסוק לא) יקום אבי:
@75 **ויאמר אני.** לא אמר אני עשו אלא אני:
@78 **וירח** וגו' **.** והלא אין ריח רע יותר משטף העזים, אלא מלמד שנכנסה עמו ריח גן עדן: **כריח שדה אשר ברכו ה'.** שנתן בו ריח טוב, וזה שדה תפוחים, כן דרשו רבותינו זכרונם לברכה:
@79 **ויתן לך.** יתן ויחזור ויתן. ולפי פשוטו מוסב לענין הראשון ראה ריח בני, שנתן לו הקדוש ברוך הוא, כריח שדה וגו' ועוד יתן לך מטל השמים וגו' : **האלהים.** מהו האלהים, בדין, אם ראוי לך יתן לך, ואם לאו לא יתן לך, אבל לעשו אמר משמני הארץ יהיה מושבך, בין צדיק בין רשע יתן לך, וממנו למד שלמה כשעשה הבית וסדר תפלתו, ישראל שהוא בעל אמונה ומצדיק עליו את הדין לא יקרא עליך תגר, לפיכך, (מ''א ח לט) ונתת לאיש ככל דרכיו אשר תדע את לבבו, אבל נכרי מחסר אמנה, לפיכך אמר (שם שם מג) אתה תשמע השמים וגו' ועשית ככל אשר יקרא אליך הנכרי, בין ראוי בין שאינו ראוי תן לו, כדי שלא יקרא עליך תגר: **מטל השמים.** כמשמעו, ומדרש אגדה יש להרבה פנים:
@80 **בני אמך.** ויעקב אמר ליהודה (להלן מט ח) בני אביך, לפי שהיו לו בנים מכמה אמהות, וכאן שלא נשא אלא אשה אחת אמר בני אמך: **ארריך ארור ומברכיך ברוך.** ובבלעם הוא אומר (במדבר כד ט) מברכיך ברוך ואורריך ארור. הצדיקים תחלתם יסורים וסופן שלוה, ואורריהם ומצעריהם קודמים למברכיהם, לפיכך יצחק הקדים קללת אוררים לברכת מברכים. והרשעים תחלתן שלוה וסופן, יסורין לפיכך בלעם הקדים ברכה לקללה:
@81 **יצא יצא.** זה יוצא וזה בא:
@84 **ויחרד.** כתרגומו ותוה לשון תימה. ומדרשו ראה גיהנם פתוחה מתחתיו: **מי אפוא.** לשון לעצמו, משמש עם כמה דברים. איפוא, איה פה, מי הוא ואיפוא הוא הצד ציד: **ואכל מכל.** מכל טעמים שבקשתי לטעום טעמתי בו: **גם ברוך יהיה.** שלא תאמר אלולי שרמה יעקב לאביו לא נטל את הברכות, לכך הסכים וברכו מדעתו:
@86 **במרמה.** בחכמה:
@87 **הכי קרא שמו.** לשון תימה הוא, כמו (לקמן כט טו) הכי אחי אתה, שמא לכך נקרא שמו יעקב על שם סופו שהוא עתיד לעקבני. תנחומא (תנחומא ישן כג) למה חרד יצחק, אמר שמא עון יש בי שברכתי הקטן לפני הגדול, ושניתי סדר היחס. התחיל עשו מצעק ויעקבני זה פעמים, אמר לו אביו מה עשה לך, אמר לו את בכורתי לקח, אמר בכך הייתי מצר וחרד שמא עברתי על שורת הדין, עכשיו לבכור ברכתי, גם ברוך יהיה: **ויעקבני.** כתרגומו וכמני, ארבני. וארב, וכמן. ויש מתרגמין וחכמני נתחכם לי: **אצלת.** לשון הפרשה, כמו (במדבר יא כה) ויאצל:
@88 **הן גביר.** ברכה זו שביעית היא והוא עושה אותה ראשונה, אלא אמר לו מה תועלת לך בברכה, אם תקנה נכסים שלו הם, שהרי גביר שמתיו לך ומה שקנה עבד קנה רבו: **ולכה אפוא מה אעשה.** איה פה אבקש מה לעשות לך:
@89 **הברכה אחת.** ה''א זו משמשת לשון תימה, כמו (במדבר יג יט) הבמחנים, (במדבר יג כ) השמנה היא, (ש''ב ג לג) הכמות נבל:
@90 **משמני הארץ** וגו' **.** זו איטליה של יון:
@91 **ועל חרבך.** כמו בחרבך, יש על שהוא במקום אות ב', כמו (יחזקאל לג כו) עמדתם על חרבכם בחרבכם, (שמות ו כו) על צבאותם בצבאותם: **והיה כאשר תריד.** לשון צער, כמו (תהלים נה ג) אריד בשיחי, כלומר כשיעברו ישראל את התורה, ויהיה לך פתחון פה להצטער על הברכות שנטל, ופרקת עלו וגו' :
@92 **יקרבו ימי אבל אבי.** כמשמעו, שלא אצער את אבא. ומדרש אגדה לכמה פנים יש:
@93 **ויגד לרבקה.** ברוח הקודש הגד לה מה שעשו מהרהר בלבו: **מתנחם לך.** נחם על האחוה לחשוב מחשבה אחרת להתנכר לך ולהרגך. ומדרש אגדה כבר אתה מת בעיניו ושתה עליך כוס של תנחומים. ולפי פשוטו לשון תנחומים, מתנחם הוא על הברכות בהריגתך:
@95 **אחדים.** מועטים:
@96 **למה אשכל.** אהיה שכולה משניכם. הקובר את בניו קרוי שכול. וכן ביעקב אמר (להלן מג יד) כאשר שכלתי שכלתי: **גם שניכם.** אם יקום עליך ואתה תהרגנו יעמדו בניו ויהרגוך, ורוח הקדש נזרקה בה ונתנבאה שביום אחד ימותו, כמו שמפורש בפרק המקנא לאשתו (סוטה יג א) :
@97 **קצתי בחיי.** מאסתי בחיי:
@99 **פדנה.** כמו לפדן: **ביתה בתואל.** לבית בתואל. כל תבה שצריכה למ''ד בתחלתה הטיל לה ה''א בסופה:
@100 **ואל שדי.** מי שדי בברכותיו למתברכין מפיו יברך אותך:
@101 **את ברכת אברהם.** שאמר לו (לעיל יב ב) ואעשך לגוי גדול, (שם כב יח) והתברכו בזרעך. יהיו אותן ברכות האמורות בשבילך, ממך יצא אותו הגוי ואותו הזרע המבורך:
@102 **אם יעקב ועשו.** איני יודע מה מלמדנו:
@104 **וישמע יעקב.** מחבר לענין של מעלה וירא עשו כי ברך יצחק וגו' וכי שלח אותו פדנה ארם, וכי שמע יעקב אל אביו והלך פדנה ארם וכי רעות בנות כנען, והלך גם הוא אל ישמעאל:
@106 **אחות נביות.** ממשמע שנאמר (לעיל כה יג) בת ישמעאל איני יודע שהיא אחות נביות, אלא למדנו שמת ישמעאל משיעדה לעשו קודם נשואיה והשיאה נביות אחיה. ולמדנו שהיה יעקב באותו הפרק בן ששים ושלש שנים, שהרי ישמעאל בן שבעים וארבע שנים היה כשנלד יעקב, ארבע עשרה שנה היה גדול ישמעאל מיצחק, ויצחק בן ששים שנה בלדת אותם הרי שבעים וארבע, ושנותיו היו מאה שלשים ושבע, שנאמר (שם יז) ואלה שני חיי ישמעאל וגו' , נמצא יעקב כשמת ישמעאל בן ששים ושלש שנים היה, ולמדנו מכאן שנטמן בבית עבר ארבע עשרה שנה ואחר כך הלך לחרן, שהרי לא שהה בבית לבן שלפני לידתו של יוסף אלא ארבע עשרה שנה, שנאמר (שם לא מא) עבדתיך ארבע עשרה שנה בשתי בנותיך ושש שנים בצאנך ושכר הצאן משנלד יוסף היה, שנאמר (שם ל כה) ויהי כאשר ילדה רחל את יוסף וגו' , ויוסף בן שלשים שנה היה כשמלך, ומשם עד שירד יעקב למצרים תשע שנים, שבע של שבע ושתים של רעב, ויעקב אמר לפרעה (שם מז ט) ימי שני מגורי שלשים ומאת שנה. צא וחשוב ארבע עשרה שלפני לידת יוסף, ושלשים של יוסף, ותשע משמלך עד שבא יעקב הרי חמשים ושלש, וכשפרש מאביו היה בן ששים ושלש הרי מאה ושש עשרה, והוא אומר שלשים ומאת שנה, הרי חסרים ארבע עשרה שנים הא למדת שאחר שקבל הברכות נטמן בבית עבר ארבע עשרה שנים. (אבל לא נענש עליהם בזכות התורה, שהרי לא פרש יוסף מאביו אלא עשרים ושתים שנה דהינו משבע עשרה עד שלשים ותשע כנגד עשרים ושתים שפרש יעקב מאביו ולא כבדו, והם עשרים שנים בבית לבן, ושתי שנים ששהה בדרך, כדכתיב (להלן לג יז) ויבן לו בית ולמקנהו עשה סכת, ופירשו רבותינו זכרונם לברכה מזה הפסוק ששהה שמונה עשר חדשים בדרך, דבית הוה בימות הגשמים וסכות הוו בימות החמה, ולחשבון הפסוקים שחשבנו לעיל משפרש מאביו עד שירד למצרים שהיה בן מאה שלשים שנים, שם אנו מוצאים עוד ארבע עשרה שנים, אלא ודאי נטמן בבית עבר בהליכתו לבית לבן ללמוד תורה ממנו, ובשביל זכות התורה לא נענש עליהם ולא פרש יוסף ממנו אלא עשרים ושתים שנה, מדה כנגד מדה) : **על נשיו.** הוסיף רשעה על, רשעתו שלא גרש את הראשונות:

@1 **ואלה תולדות וגו'**. צריך לדעת א' במקום שיזכיר תולדות יצחק הזכיר לידת יצחק, ב' לא היה צריך להודיע כי אברהם הוליד את יצחק:
@1 **אכן** כוונת הכתוב היא על זה הדרך **ואלה תולדות יצחק** פירוש האמורים בסוף הפרשה וכיון שזכר בניו של יצחק וכבר קדם לנו כי יצחק כשנולד לא היה במדרגה שיוליד כי בא מסטרא דנוקבא וכמו שכתבנו למעלה (לעיל כ''ב ב') אם כן מנין לו תולדות לזה גמר אומר **אברהם הוליד את יצחק** פי' הפעיל כח הלידה ביצחק שהמשיך אליו נפש שהיא במדרגת המוליד וזה היה באמצעות העקידה כמו שכתבנו:
@1 **עוד** ירצה על דרך אומרם ז''ל (יבמות סד.) ויעתר לו ה' לפי שאין דומה וכו' לתפלת צדיק בן צדיק ע''כ. הא למדת כי לצד היות לו אב צדיק נתרצה ה' לו ונתן לו בנים, והוא אומרו **אברהם הוליד** וגו', פי' באמצעות זכות אברהם הוליד וגו':
@1 **עוד** ירצה על פי דבריהם ז''ל (בראשית פס''ג) בפסוק (ישעי' כט כב) אל בית יעקב אשר פדה את אברהם כי בזכות יעקב ניצול אברהם מכבשן האש וזולתו כבר היה ח''ו אברהם נשרף באור כשדים, והוא אומרו **אלה תולדות יצחק בן אברהם** שבאמצעות' אברהם הוליד את יצחק כי זולת יעקב שהוא תולדות יצחק כבר היה אברהם נשרף קודם שיוליד יצחק:
@1 **עוד** ירמוז על עיקר תולדות הצדיקים שהם מצות ומעשים טובים, כי להיות שיצחק לא נודעו נסיונותיו וגדר צדקותו, והגם שפשט צוארו על גבי המזבח אין דבר זה מבואר בתורה ועד היום יש מפרשים (ראב''ע כב ד) כי בעל כרחו נעקד, לזה מודיע הכתוב באומרו ואלה תולדות יצחק בן אברהם הבט וראה המוליד והמורם כיוצא בו. ורמז גם כן בתיבת **בן אברהם** על דרך אומ' (משלי י') בן חכם פי' כי הוא אברהם בבחינת הצדקות והפלגת חיבתו יתברך. וכפי זה ידוייק גם כן אומרו **ואלה** בתוספת וא''ו לומר מוסיף על תולדותיו של אברהם המפורסם לטובה בכמה נסיונות גם תולדותיו של יצחק בדומין:
@1 **עוד** ירמוז על זה הדרך ואלה תולדות יצחק בן אחד היה אברהם פירוש כדומה לו שלא דמו לאברהם ב' תולדותיו של יצחק:
@1 **עוד** ירמוז באומרו **אברהם הוליד** וגו' על זה הדרך שהגם שדימה תולדות הטוב של יצחק לשל אברהם כרמוז באומרו ואלה בתוספת וא''ו עם כל זה לא תשוה מעלתו לשל אברהם כי הוא האב זיכה לו, והוא אומרו **אברהם הוליד את יצחק** בחינת הטוב שבו באה מכח המוליד מה שאין כן אברהם כי אביו עובד עבודה זרה היה והוא נתעצם להשיג בוראו ומעלת אברהם נשגבה, ולזה נקרא (ישעי' מא ח) אברהם אוהבו יתברך פי' הוא קדם להיות אוהב לקונו קודם שיאיר ה' אליו אהבתו בו הוא רדף אחריו בהתעצמות נפלא מה שאין כן יצחק כי בנה בו אברהם בנין אהבת הטוב וכשפקח עינו בעולם כבר נחה עליו רוח ה':
@1 **עוד** ירמוז על זה הדרך כי תולדות יצחק היה בבחינת יותר מעולה מתולדות אברהם כי אינו דומה צדיק בן צדיק לצדיק בן רשע (יבמות סד) שהוא אברהם בן תרח, והגם שאמרו ז''ל (ב''ר פל''ח) שעשה תשובה עם כל זה בעת לידת אברהם עד סמוך למיתתו לא היה אלא במדרגת רשע ופעולת האב רשע תחשיך מאור נפש הבן, ובבחינה זו נתרבית הכשרת מעשה יצחק, והוא אומרו **ואלה** בתוספת על הראשון ונתן טעם באומרו אברהם הוליד וגו':
@1 **עוד** נתכוון לומר על זה הדרך **אלה תולדות** פירוש מאורעות אשר עברוהו ליצחק כמפורשים בסדר הפרשה וכאומרם ז''ל שכולם שלמים בלא שום מאורע של צער וברוב טוב עושר וכבוד וכמבואר בפי' רמב''ן ז''ל (כ''ה ל''ד) מה שלא היה כן לאברהם שכמה עברוהו מהצרות, ונתן הכתוב טעם לצד כי אברהם הוליד את יצחק ולצד שאביו צדיק היה וזיכה לו העושר והכבוד וכו' מה שאין כן אברהם שלא היה לו אב שיזכה לו:
@2 **ויהי יצחק בן ארבעים וגו'**. טעם שהוצרך להודיע זמן נישואיו מה שלא נהג כן באברהם, בא לתת טעם לעיכוב הזמן ששהה יצחק בלא נישואין עד עבור מ' שנה ואמר הטעם **בקחתו את רבקה** בשביל קיחת רבקה שהה עד מ' שנה וכמו שגמר אומר **לו לאשה** פי' לו מיוחדת היא בת זוגו הא למדת שקודם לה לא היתה לו בת זוג וכמו שכתבנו בפרשה הקודמת והיא קטנה היתה שנולדה בעקידה כשהוכשר לילד ומעתה אין תרעומת על יצחק ששהה עד מ' שנה גם על אברהם שעכב עד מ' שנה כי אז היתה בת ג' שנים כפי החשבון:
@2 **בת בתואל הארמי וגו' אחות וגו'**. טעם שחזר הכתוב להודיע זה לא להשמיענו בת מי היא אלא ללמד סניגוריא על רבקה, לפי שאומר בסמוך ויעתר לו ה' לו ולא לה, ותבא הסברא לומר כי טעם הדבר לצד פחיתות רבקה ח''ו כי לא ראויה היא לשמוע אליה אלהים, לזה הקדים לומר **בת בתואל** לומר כי זו היא סיבה למה שהעתיר ה' ליצחק כי הוא בן אברהם והיא בת בתואל, וכפל לומר **הארמי מפדן ארם** להעיר כי נתכוון באומ' הארמי לומר הרמאי כי אם נתכוון לכנותו לשם עירו הרי הוא אמור, והכוונה בזה לצד שלא נתפרסם רשעותו בעולם בא להודיעו כי רשע היה ובאמצעותו לא הוכשרה תפלת רבקה כתפלת יצחק:
@2 **ואומרו אחות לבן** ללא צורך ונוסף שכבר ידענו אלא הטעם הוא שבא ללמד זכות על רבקה בראותינו שילדה בן רשע מובהק, ותאמר איך מבטן ברוך יצא ארור, לזה אמר כי זה הוא סיבה לדבר היותה אחות לבן הארמי פירוש הרמאי בתוספת רשע על אביו, וכבר קדמו חז''ל (ב''ב קי.) רוב הבנים, לטעם הידוע, ולזה יצא עשו, וזולת זה צאצאיה צדיקים היו יוצאים ממנה, כי צדקת גמורה היתה, והעד לנוכח אשתו, ואמרו ז''ל (ב''ר פס''ג) וכו'. ושלא תאמר ואם כן ולמה לא נתן לב יצחק לבדוק באחיה, לזה גמר אומר **לו לאשה** וכמו שפירשתי למעלה, וזולת זה לא היה נושא אחות רשע:
@2 **עוד** רמז בהודעת **אחות לבן** על דרך אומרם ז''ל (שם פ''ס) שטעם רבקה שהיתה עקרה הוא לצד ברכת לבן כדי שלא יראה כי ברכתו תעשה מעשה טוב, לזה קודם שאמר הכתוב כי עקרה היא קדם לומר טעם הדבר ואמר אחות לבן וזו היתה סיבה שנעקרה רבקה עד שהוצרכו לתפלה:
@3 **ויעתר לו וגו'**. טעם שלא אמר וידע יצחק את וגו' כאומרו (בראשית ד' א') והאדם ידע (ש''א א) וידע אלקנה וגו' אולי שהיתה התפלה אחר שידע (ברכות ס.) תוך ג' ימים הראשונים כאומרם ז''ל (ברכות ס.) שלשה ימים הראשונים יתפלל שלא יסריח, וזו היתה תפלתו של יצחק:
@4 **ויתרוצצו הבנים וגו'**. צריך לדעת אומרו **ויתרוצצו**. גם אומרה **למה זה אנכי**. ורש''י פי' אם כן גדול צער העיבור למה זה אנכי מתאוה ומתפללת על ההריון ע''כ. ופירושו ז''ל אין הדעת מסכמת עליו שתמאס הצדקת בהריונה לצד הצער, גם במה נחה דעתה באמור לה האלהים ב' גוים וגו' ובזה לא יוסר צערה. ורז''ל דרשו דרשות הרבה אבל פשט הכתוב לא נודע. אכן פשט הכתוב הוא **ויתרוצצו** לשון ריצוץ פירוש היו נדחקים ביותר כשיעור שיהיו מתרוצצים ולא יתקיימו במעיה וזה יורה כי הריונה אינו מתקיים, **ותאמר אם כן למה זה אנכי** פי' זה מורה באצבע חוזר אל ההריון למה אנכי הרה לריק יגעתי, **ותלך לדרוש את ה'** פי' לבקש רחמים על קיום הריונה ולדעת דבר הסובב הפסדם כי מן השמים לא יעשו נס לשקר שתפקד בדבר שאינו מתקיים, ולעולם לא הקפידה על צער ההריון כי הצדיקים יסבלו צער גדול בעולם הזה לתכלית טוב הנצחי:
@5 **ויאמר ה' לה וגו'**. מקרא זה רבו בו הפירושים ועודנו בר נתינת טעם ותבלין בדרך אור ישר, והוא כי בא להשיבה על חששתה שאין הריונה מתקיים לרוב דחקם והודיעה סיבת הדוחק אשר ידחקו זה את זה ויתעצמו זה על זה כי משונה הריון זה מכל הריון שבעולם כי כל הריון שיהיה מב' יהיו הב' נוחים וטבעם שוה כאומרו (שיר השירים ז ד) תאומי צביה וידורו יחד בבטן מה שאין כן הריונך, והטעם הוא **כי ב' גוים בבטנך** כל אחד מהם הוא בחינת גוי אחד, ועוד להם שהם עצמם הם מלכים ומלכותם נמשכת לעולם והוא אומרו **וב' לאומים**. וכל זה לא יסובב להתרוצץ בבטן אם היו במזג אחד כטבע התאומים אלא שהם משונים מטבע התאומים כי מהבטן עצמו אינם נוחים זה לזה ומשונה מזגם וטבעם, והוא אומרו **ממעיך יפרדו**, ואמר **ממעיך** ולא אמר במעיך לומר כי תמיד הם מפורדים והתחלת הפירוד ממעים, ובאמצעות ענין זה הוא השינוי המופלא לא לצד כי אין בטנה ראוי להריון מתרוצצים הבנים:
@5 **ואומרו ולאום מלאום** וגו', פי' עוד יש להם דבר שיגרום הרחקת הכנת ההתגוררות יחד כי כל אחד מהב' מלכים חזקו ואמצו הוא מלאום שכנגדו על דרך אומרם ז''ל (מגילה ו.) לא נתמלאה צור אלא מחורבנה של ירושלים, וכיון שכל אחד מהם רוצה במפלת חבירו כדי שיגדל ממנו זה ירחיק האחוה והתיאום יחד:
@5 **ואומרו ורב** וגו' רבו בזה הפירושים ואין דבר מספיק באמיתות הכתוב. ולדרכנו יבא על נכון, הכונה בא לומר כי מלבד שיתגדל אחד במפלת חבירו גם צריך הנופל להשתעבד לפני המתגדל ממנו ולא די לו נפילתו וראות טובו ביד אויבו אלא שיכוף כאגמון ראשו לעובדו ובזה תפליג הרחקת האחוה ותעצומת השנאה, ועל זה נאמר (כתובות עב.) אין אדם ונחש דרים בכפיפה אחת. וזאת סיבת שינוי ההריון. וכפי דרך זה אומרו **ורב יעבוד צעיר** אין הכונה באומרו רב וצעיר בייחוד על יעקב או על עשו אלא על אשר יהיה רב בזמנו ועל אשר צעיר בזמנו, כפתור ופרח:
@8 **ויקרא שמו יעקב**. פי' הקב''ה לא אביו והעד הנאמן אומ' ויצחק בן ששים וגו' ואם הוא הקורא היה לו לומר והוא בן ששים וגו' שבו משתעי קרא והבן:
@10 **ויאהב יצחק וגו'**. הנה לדבריהם ז''ל (תנחומא) שאמרו שהיה צד אביו בדברים היאך מעשרין את המלח לא חש לעשות כן אלא ליצחק ולא לרבקה כי לא לצד המצוה היה חושש אלא לצד שהיה ירא מקללתו גם לתקות הברכות, מה שאין כן רבקה. ולזה תמצא שלא אמר יקרבו ימי אבל אבי ואמי אלא אבי, וטעם רבקה שלא הגידה ליצחק רשעו אפשר שהיה מרמהו שלא בפניה לבל דעת סיבת אהבתו אותו להסירה. ולפי אונקלוס שתרגם ארי מצידי' הוה אכיל צריך לדעת למה לא יועיל טעם זה גם לרבקה כי מן הסתם לא יפליג עצמו יצחק מרבקה. ואולי כי רבקה חיובה על יצחק להאכילה בשר וכמו שכתב מהרי''ק באבן העזר (סי' ע' סעיף א') שחייב במזונותיה ואם בני משפחתה רגילים בגדולות צריך להנהיגה כן ע''כ, וידוע כי בתואל שר וגדול לארם לזה לא תחזיק טובה לטרף בפ יה:
@11 **ויזד יעקב**. אולי כי לצד שראה שהועילה לגימתו של עשו ליצחק לקח גם הוא דרך לבשל תבשילין לקרב לב אביו אליו כעשו:
@12 **על כן קרא שמו וגו'**. פי' הוא עשו קרא שמו אדום, והטעם לא לצד שקרא שם האדום האדום שני פעמים אלא לצד שהיה הולך למות ובו החיה נפשו קרא שמו אדום בשמו, ועשו בדיק בשמא היה כאומרו (כ''ז ל''ו) הכי קרא שמו וגו':
@13 **ויאמר יעקב מכרה כיום וגו'**. צריך לדעת אומרו **כיום** שאין לה משמעות. ונראה כי להיות כי בכורה זו שקונה ממנו יש בה פרטים שאינם במציאות אלא במות אביו והם דברים שלא באו לעולם, וכפי תורתינו הקדושה אין אדם מקנה דבר שלא בא לעולם, לזה נתחכם לומר כיום כדי שתתקיים המכירה. והוא על פי מה שאמרו במסכת מציעא דף ט''ז ופסקוהו הפוסקים (חו''מ ס' רי''א סעי' ב') הצייד עני שאין לו מה יאכל שאמר מה שיעלה במצודתי היום מכור לך ממכרו קיים, והטעם משום כדי חייו, וכתבו הגאונים שאין הטעם תלוי באומר היום אלא הוא הדין יום אחר ממכרו קיים מטעם כדי חייו ולא אמרו היום אלא לשלול מה שיעלה במצודתו ל' יום או שנה שהוא יותר מכדי מחיית יום אחד, אבל מחיית יום אחד בכל מציאות שיהיה קיים. והוא אומרו **מכרה כיום** פירוש כדין יום שהרי עיף היה ומשום כדי חייו ממכרו ממכר הגם שהוא דבר שלא בא לעולם, וזולת מציאות זה אין דין שיכול לזכות במכר הבכורה, והצדיק עשו דברי יעקב כאומרו הנה הוא הולך למות ואין לך תקנת משום כדי חייו גדולה מזו:
@15 **ויאמר השבעה לי** טעם שהוצרך לשבועה. להיות כי יש בבכורה פרטים שהם דברים שאין בהם ממש, כמו הכבוד והמעלה, שעליהם הקפיד יעקב לעבודת בית אלהינו שהיא בבכורות, וכפי תורתינו הקדושה אין אדם מקנה לא במכר ולא במתנה דבר שאין בו ממש כידוע, (רמב''ם הלכות מכירה פ' כ''ב) לזה נתחכם לזכות בדבר על ידי שבועה וכן הוא הסכמת פוסקי התורה (יו''ד סי' רל''ט) כי השבועה חלה בין על דבר שיש בו ממש בין על דבר שאין בו ממש, והוא אומרו **השבעה לי**. והנה שבועה זו לא תספיק לקנין דבר שלא בא לעולם, כי טעם דאין אדם מקנה דבר שלא בא לעולם היא לצד דלא סמכא דעתיה דלוקח וכו', וכן מוכח במציעא דף י''ו, אבל אם היה דעתו סומכת היה נקנה ושבועה לא תועיל בזה ולכן הוצרך לטעם כיום כמו שפירשתי. שוב בא לידי ספר הריב''ש סי' שכ''ח וז''ל כתבת שראית ר''י בן הרא''ש שכתב בשם אביו דמקנה דבר שלא בא לעולם אם נשבע קנה וכו' וראייתו ממכירת בכורה שמכר עשו ליעקב וכתיב השבעה לי עד כאן. תשובה, לא הרא''ש ולא ר''י בנו חתימי עלה ואין לתלות בגברי רברבי סברא כזו שאין לה על מה שתסמוך, גם הראיה שהביאו אין לה עיקר לפי שהיה קודם הדיבור ומאן לימא לן שלא היה אדם מקנה דבר שלא בא לעולם אז, והשבועה היתה לרווחא דמלתא שלא יערער לפי שהיה איש זרוע ע''כ. והם דברינו עצמן אלא שהריב''ש לא התבונן לתת טעם שהוצרך שבועת עשו כמו שכתבתי:
@15 **וטעם** אומרו **השבעה לי** ולא הספיק לומר השבעה והדבר מובן כי לו היא המכירה, נתכוון לומר כי שבועה זו צריכה להיות על דעתו של יעקב שזולת זה יכול לבטלה בלבו ועיקר השבועה צריכה להיות בלב כדאמר רבי עקיבא (תו''כ פ' י''ב) האדם בשבועה שיהיה פיו ולבו שוים בשעת השבועה לזה אמר השבעה לי פי' לדעתי:
@15 **גם** דקדק לומר **לי** כי דוקא הוא שיכול להתקיים מכר הבכורה בכל חלקיו אבל לא לזולת כי הזולת אינו בן קנייה אלא דברים שהם ממון אבל דברים שהם ירושה מעלות מאביהם כגון העבודה שבבית אלהים והכבוד אינם באיש נכרי ולאו כל כמיניה למכרם לזר:
@15 **וימכור את בכורתו**. הצדיקה התורה המכירה שקיימת היא בידו מטעמים שכתבנו והגם שלא מכר אלא לאונסו, והגם שמכר דבר שוה מאה מנה במנה. וזה לך לשון מהרי''ק (חו''מ רכז) אם מכר מפני דוחקו וזלזל במכירתו יותר מכדי שהדעת טועה שניכר שמפני דוחקו הוצרך לזלזל אינו יכול לחזור בו דידע ומחל עכ''ל. ומעתה הגם שמכר דבר מופלג הערך בלגימה אחת של נזיד ממכרו מכר כמו שגילה הוא דעתו באומרו הנה הוא הולך למות ואין לך דוחק גדול מזה, (איוב ב') עור בעד עור וכל אשר לאיש יתן בעד נפשו, והנה זולת המצאה זו לא היה מציאות ליעקב לזכות בבכורה מיד עשו, ועל עשו אמר הנביא (משלי ה') עונותיו ילכדנו את הרשע שבסיבת עונותיו שעשה בו ביום כאומרם ז''ל (ב''ר פס''ג) בפ' אומרו והוא עיף (ויגע) זה היה סיבה להוציא ממנו הבכורה ותעמודנה ביד הראוי לה:
@16 **ויקם וילך ויבז עשו וגו'**. פי' התורה מעידה עליו שביזה הבכורה בדעתו. ולזה לא הספיק לומר ויבז וחוזר אל עשו האמור בסמוך, והבן. וכונת הודעה זו לומר גם בלא טעם דלאונסו גמר כי בעיניו בזויה היא ומכור ימכרנה בדבר מה הגם שלא היה צריך להשיב נפשו וגמר ומקנה:
@18 **שכון בארץ אשר וגו'**. נתכוין לומר סתם לקבל עליו אמרי קדוש אל המקום אשר יאמר אליו הגם שיהיה הפך רצונו, וליטול שכר על הדבר, כי רצה הקב''ה לזכות ידידיו וכן הוא אומר (לעיל יב א) אל הארץ אשר אראך וסמוך הזכירה לו דכתיב (שם ה) ללכת ארצה כנען:
@19 **כי לך ולזרעך וגו'**. ארץ פלשתים בכלל נתינת הארץ היא, ולזה גם כן הסכים רמב''ן, ואומרו **לך** הבטחה זו אולי שהיא על מה שהצליח הוא שם דכתיב (פסוק יב) ויזרע יצחק בארץ ההיא וגו'. עוד נתכוון לומר לו שיזכה הוא בה לזרע, ואולי כי לא החזיק אברהם בארץ פלשתים בחזקה הראשונה לזה רצה ה' שיחזיק יצחק בה והוא החזיק בה בחזקה מעולה שחרש וזרע, ולזה דקדק ה' בדבריו לומר את כל הארצות האל:
@19 **עוד** נתכוין להבטיחו כי אין לישמעאל חלק ונחלה בהבטחות אברהם זולת ליצחק לבד והוא אומרו **לך**. ודקדק לומר **ולזרעך** לשלול חלק מבניו כי דוקא אותו שנקרא זרעו דכתיב (כ''א י''ב) כי ביצחק יקרא לך זרע (נדרים לא) ולא כל יצחק:
@21 **שמע אברהם בקולי**. לכל אשר נסיתיהו, **וישמור משמרתי** שמר עצמו לבל יבא לידו דבר שצויתיהו לשמור, וכמו כן שמר המצות לבל יעברוהו בהסח הדעת. וחקותי הם מצות שאין בהם טעם, וכמו כן תורתי שמר לבל תשכח ממנו על דרך אומרו (דברים ד) ושמור נפשך וגו' פן תשכח את הדברים וגו':
@22 **וישב יצחק בגרר**. לומר שקיים מאמר הבורא ברוך הוא ובטל מחשבתו שקדמה לו:
@24 **מצחק את רבקה**. פי' מעשה חיבה הנעשית בין איש לאשתו ולדברי האומר (ב''ר פס''ד) מצחק משמש מטתו אולי שהיה באחד מהדרכים שמותר אפי' ביום כמו שתאמר לרפואה וכמו שכתב רמב''ם (הלכות דעות פ' ד') או כמעשה שהובא בש''ם (כתובות סה) דביתהו דאביי דגלית וכו' ואזל רבא וכו' כי הצדיקים יחושו לדומה דדומה דכיעור לבל יכשלו בו:
@27 **מות יומת**. פי' מות בידי שמים יומת בידי אדם, ודקדק לומר **הנוגע** לומר אפילו בדרך שאינו נהרג על אשת איש דבני נח יהרג על זאת וכמו שכתבנו במעשה שרה בפרשת וירא (כ ד):
@28 **מאה שערים ויברכהו**. פי' להיות דדבר הנמדד אין הברכה מצויה בו (ב''מ מב.) וכאן אמר שהגם שנמדד ונודע שיעור מאה שערים אף על פי כן **ויברכהו ה'**. עוד ירצה שלא נכנם בו עין הרע מהפלגת הריוח כי יצו ה' אתו את הברכה:
@31 **וכל הבארות וגו'**. סמך הודעה זו לויקנאו וגו', לומר כי לא ינוח שבט הרשע על גורל הצדיקים, והודיע שקנאו ממנו, והוסיף להודיע שגם עם אברהם היה להם קנאה ושנאה וכל הבארות אשר וגו'. ואומרו **סתמום וימלאום עפר** ולא הספיק לומר מלאום עפר, אולי כי אחר מות אברהם סתמום דוקא עשו אבנים לפיהם ולא בטלום בהחלט, ואחר הקנאה שקנאו ביצחק ויוסיפו להרשיע בקנאתם וימלאום עפר והיו כלא היו, ולזה הוצרך יצחק לחפור אותם מחדש כאומרו בסמוך ויחפור את בארות וגו':
@32 **כי עצמת ממנו וגו'**. פי' ואין גדולת המלכות ניכרת לפני גדולתו ואין לך בזיון המלך כזה:
@33 **ויחן בנחל גרר**. כי לא רצה לעקור את דירתו מארץ פלשתים בהחלט לצד מצות המלך מלכו של עולם היא לאמר (פסוק ג) גור באדץ הזאת, והגם שנאמר שהמקום ההוא לא היה בכלל מה שאמר לו ה' שכון בארץ אף על פי כן אנוס היה מהמלך אדון הארץ. ואולי כי עשה ה' ככה לנסיון שהגם שאמר לו ה' לך ולזרעך אתן את כל הארצות אף על פי כן לא נתנוהו אפי' לשבת שם כאחד העם אם לא יהרהר אחר השכינה, וכמו כן עשה לאברהם:
@40 **אל תירא כי אתך וגו'**, פי' להיות שראה השפלה ממלך פלשתים שגרשו מארצו ולא ידע אן יפנה חש כי ה' עזבו לזה אמר אל תירא לא עזבתיך אתך אני:
@42 **ואבימלך הלך אליו מגרר וכו'**. צריך לדעת למה הוצרך לומר **מגרר** והוא דבר ידוע. גם אין צורך בהודעה זו. ורז''ל הרגישו ודרשו (ב''ר פס''ד) מגורר וכו' וזה דרך דרש. עוד למה הוצרך לקחת עמו פיכל ואחוזת מרעהו, ואם לטכסיסי מלוכה לא היה צורך לכתוב להודיע דברים שאין לנו בזה צורך:
@42 **אכן** כוונת הכתוב היא לתרץ מה שיקשה לנו למה הוצרך אבימלך לחזר אחר יצחק לכרות לו ברית ללא צורך כי כבר נשבע לו אברהם (כא כג) אם תשקור לי ולניני ולנכדי, ומה מיחוש היה לו לאבימלך בשבועת אברהם שהוצרך לשבועת יצחק, ורמב''ן ז''ל הרגיש ליישב ואמר שיראת אבימלך שיצחק יפר הבטחת אברהם לצד שהם הפרו ברית וגרשוהו מאתם ע''כ. ולא ראיתי שהתנה אבימלך לאברהם בשבועתו לשבת בארצו הוא ובניו ואין הפרת ברית במה ששלחו יצחק, ועדיין קושיא במקומה עומדת שלא היה צריך לברית יצחק. אשר על כן בא הכתוב ואמר **מגרר** פי' מטעם גרר יש מקום לחוש לביטול ברית אברהם והוצרכו לחזק ברית עם יצחק. והוא על דרך מה שאמרו בנדרים דף ס''ה וז''ל תניא המודר הנאה מחבירו אין מתירין לו אלא בפניו. וכתבו הגהות מיימוניות בפ''ו מהלכות שבועות וז''ל ואמר ר''י ודוקא לכתחלה צריך בענין זה אבל לא דיעבד ולכתחלה לא אמרו אלא באדם העושה לו טובה כגון משה שנתן לו יתרו בתו וצדקיהו שהוציאו נבוכדנצר ממאסר וכו' אבל אדם אחר אפילו לכתחלה כדמוכח מפרק אלו נאמרין וכו' (סוטה לו) ע''כ. הנה מוכח כפי זה שיכול הנשבע על דעת חברו לעשות התרה אפילו לכתחלה אפילו שלא בפניו ואין צריך לומר דיעבד כל שלא קבל הנאה ממנו. ויש לך לדעת כי אברהם לא קבל הנאה מאבימלך כי מה שנתן לו מתנות הוא לצד כלימת שרה ומה שנתן לו לשבת בגרר לא קבל אברהם, וכמו שנראה מהכתובים כי פנה תיכף והלך לו מגרר וישב לו בבאר שבע מקום שגר שם יצחק אחר שלוחו מגרר. ושוב בא לידי מאמר אחד (ב''ר פנ''ד) וז''ל כחסד אשר עשיתי וגו' מה חסד עשה עמו שאמר לו הנה ארצי לפניך וגו' והוא לא קבל ע''כ. הרי שסוברים רז''ל שהחסד שעשה עמו שאמר לו הנה ארצי לפניך וגו' לא קבלו, והגם שאומר כחסד הם דברי עצמו ואינו כן, ולא כן היה ביצחק שהושיבו בארצו וישב שם ועשה והצליח בכל טוב, והוא אומרו **ואבימלך הלך אליו** והטעם מגרר פי' מדין הנמשך מאמצעות גרר, כי לאברהם לא היתה טובת גרר טובה שהוא לא קבל ושבועתו ישנה בהתרה וליצחק היתה הטבה ולזה תתקיים השבועה כשתהיה בשביל הטובה ואינו יכול להתיר שלא ברצונו של אבימלך:
@42 **ועוד** אפי' אם תמצא לומר כי אבימלך כשהשביע אברהם היה דעתו הפך דעת ר''י שכתבו הגהות מיימוניות והיה סובר כרמב''ם שכתב בפ''ו מהלכות שבועות דכל שהשביע חבירו על דעתו הגם שלא קבל ממנו הנאה אין מתירין לו אלא בפניו אף על פי כן לא סמך בדעתו על השבועה כי מודה שאם דיעבד התיר שבועתו מותרת כיון שלא היתה טובת הנאה באמצע, ודין זה שוים בו כל המורים, לזה הלך ליצחק שהיתה לו טובת הנאה, ובזה כתבו הראב''ד והרשב''א והאחרונים שהגם שהתיר דיעבד אינו מותר. גם נתחכם לקחת אחוזת וגו' ופיכול לחזק השבועה כאשר אבאר:
@42 **ואחוזת מרעהו ופיכול וגו'**. צריך לדעת למה הוצרך לקחת עמו אחוזת מרעהו מה שלא עשה כן בימי אברהם:
@42 **אכן** יתבאר הענין על פי מה שנסתפק ר''ת (ר''ן נדרים סה.) בהנשבע על דעת חבירו בשביל הטבה אם דיעבד התירוהו אם מותר או לא ולא הוכרע. ולסברא זו חש אבימלך גם לשבועה זו הגם שהוא בשביל טובה, ונתחכם לעשות חיזוק שלא תועיל לו ההתרה, והוא על דרך מה שאמרו בגיטין דף מ''ו מחלוקת ר' יהודה ורבנן ר''י סבר נדר שהודר ברבים אין לו התרה כיון דנדר בפני רבים שוב אינו יכול להתיר ורבנן סברי יכול להתיר. ואמרו בגמ' דף ל''ו אמר אמימר אפילו למ''ד נדר שהודר ברבים יש לו התרה נדר שהודר על דעת **רבים** אין לו התרה ע''כ. וכתבו התוספות דאיכא פנים לומר שלא דחה אמימר דעת ר''י שאמר נדר שהודר בפני רבים אין לו התרה. וגם מדברי רב יוסף (פסחים קז) נמי מוכח דהלכה כר''י ובמסקנת דבריהם העלו דהלכה כרבנן והגאונים פסקו כר''י. וכפי זה נתחכם אבימלך להביא עמו רבים אחוזת וגו' ופיכול כדי שידור בפני רבים. והנה נחלקו אמוראים בגיטין (מו.) וז''ל ידעו בו רבים כמה רבים רב נחמן אמר ג' ר' יצחק אמר עשרה, והצצתי בדברי רז''ל שנחלקו בב''ר רבי יהודה ור' נחמיה וז''ל ר''י אומר אחוזת מרעהו שמו ר' נחמיה אומר סיעת מרחמוהי ע''כ. ואולי כי מחלוקתם תלויה במה שנחלקו האמוראים חד אמר שלשה וחד אמר עשרה ר''י שאמר אחוזת שמו סובר כמה רבים שלשה ולזה אמר אחוזת שמו ורבי נחמיה סובר עשרה לזה אמר סיעת וגו' שבזה היו עשרה לתכלית הכוונה כדי שיהיה על דעת רבים שאין לו התרה וכדעת ר''י:
@42 **ואפשר** שנתחכם גם לדעת רבנן שאמרו שישנו בהתרה ולזה הביא פיכול, וכדברי אמימר שיודו רבנן בנדר על דעת רבים שאין לו התרה לזה הביא פיכול ואמר ר' נחמיה פי שכל צבאות וכו' ע''כ והשביעו אבימלך ליצחק על דעת כל צבאותיו:
@42 **וראיתי** כי רבי יהודה ור' נחמיה שנחלקו בפירוש אחוזת וגומר נחלקו גם כן (ב''ר פס''ד) בפי' פיכול, ואפשר כי טעם אחד לב' המחלוקות ר''י שסובר אחוזת שמו וסובר כיון שטעם אבימלך הוא שיהיה הברית בפני רבים ורבים הם ג' לזה הניח הכתוב כפשוטו ג' המה רבים אבימלך ופיכול ואחוזת ור''נ שלא הספיק לו לקראות רבים ג' ופי' אחוזת סיעת מרחמוהי אם כן פיכול זה למה הביאו וכי הביאו למה הוצרך הכתוב להזכירו כי העשרה הנה הנם בסיעה שאין סיעה פחות מעשרה לזה פי' פי שכל וכו' ולמדה אחרת נתכוין שתהיה על דעת רבים כמו שכתבתי ולא יקשה בעיניך מה שפירשנו שנחלקו התנאים במה שנחלקו האמוראים, כזה הם רבים כי לא היו האמוראים בקיאים בברייתות ובפרט באגדות:
@43 **ויאמר אליהם יצחק**. צריך לדעת איך יענה יצחק למלך ושריו מדוע באתם אלי כי אין זה מהמוסר. ועוד סוף מעשיו הוכיחו הפך זה כי כרת להם ברית. עוד אחר שאמר ואתם שנאתם אותי מה מקום להאריך לומר ותשלחוני וגו'. ואם הוכחה לשנאה הוא אומר ותשלחוני היה לו לומר כי שלחתם אותי וגו'. אכן כוונת יצחק היא למה שהשכיל כי אין מציאות שיצטרך אבימלך ליצחק בשום אופן זולת בענין פחדו על נחלתו לבל ישלחו יד בה לצד מתנת האדון ודבר זה כבר נשבע אברהם וכמו שהקשינו במקומו למה הלך אליו, ויצחק היה לבו שלם לבל יריע את הברית אשר כרת את אברהם אביו כי פסק הלכה כהרמב''ם שכל שנדר על דעת חברו צריך להתירו בפניו פירוש בידיעתו ואברהם כיון שלא התיר בפני אבימלך השבועה כראי מוצק (איוב ל) שאין הבנים יכולין להתירה עוד, ומעתה אין צורך להם ממנו, ובבחינה זו אמר מדוע באתם, אלא ודאי שאין ביאה זו אלא לצורכי יצחק להטיב לבו ולהשיבו אל המקום, לזה אמר תיבת **אלי** פי' ואם הביאה היא לצורכי גם עליה אני דן כי זו רחוקה היא מהאמין כי אתם וגו', דקדק לומר **ואתם** לומר מלבד כל אנשי העיר גם המלך ושריו שנאתם אותי ושנאה זו אינה תלויה בדבר אלא לצד שקנאתם בי ולא יכולתם להניח אותי עמכם בעיר והוא אומרו **ותשלחוני** וגו' וזו שנאה מחמת קנאה והנה ידוע הוא כי כל שנאה שהיא תלויה בדבר בטל דבר וכו' אבל שנאה מחמת קנאה אינה בטילה עולמית זולת בהבטל הדבר שבאמצעותו היתה הקנאה, ומעתה לא ישתנה הדעת בכם להסיר שנאתכם ממני:
@44 **ויאמרו ראו ראינו וגו'**. צריך לדעת למה כפל לומר ראו וגו' גם שאר הדקדוקים:
@44 **אכן** נתכוונו להשיב לכל מה שיסבול דברי יצחק באומרו מדוע וגו', ואמרו לצד שכוונתך כבר נשבע לנו אביך ראו ראינו וגו' ב' ראיות הא' כי שבועת אברהם אין לסמוך עליה מטעמים שכתבנו למעלה, עוד ראינו כי באמצעותך תתקיים השבועה כראי מוצק. עוד ראינו כי שבועת אביך לא דקדקנו לפסקי דינים המפסידים הברית וכמו שכתבנו למעלה, גם אם כוונתך לומר על אשר לא הלכנו לישמעאל לכרות לנו ברית כי הוא מיורשי אביך והוא הגדול ראינו כי ה' עמך וזה לך האות כי הבטחות אברהם לך הם נתונים ואתה העיקר בהם, גם אם כוונתך לקבול על אשר הראנו לך שנאה במה ששלחנוך ראינו כי ה' עמך ובערך אדם כזה בכל מקום שהולך שמה שמור ומוצלח הוא ולא ישתנה לו המקום בערכו ואין כאן שנאה:
@44 **גם** למה שתהיה ההקפדה על המתגלה מלבבנו כי לא נכון עמך ותאמר איך תבקשו ממני טובה, גם לזה באה תשובה באומרם **ראו ראינו** ראיה שכליית שזולת זה לא תתקיים השבועה בינינו בכל תוקף המשפט וכמו שדקדקו בדבריהם כאשר אבאר בסמוך:
@44 **ונאמר תהי נא וגו'**. צריך לדעת אומרו ונאמר לשון עבר. התחילו לתת טעם לאשר שלחוהו, כי קודם והוא עמם בגרר לא תכון השבועה על דרך מה שאמרו ז''ל בנדרים דף כ''ז וז''ל נודרים להרגים וחרמים וב''ה אומרים אף בשבועה. וכתב מהרי''ק בסימן רל''ב וז''ל הנודר או הנשבע לאנס לא הוי נדר ולא שבועה וכו' (וחוזר) [וחושב] בלבו וכו', ולפי זה כל השבועה שתהיה תחת יד אנס יכול הנשבע לבטל בלבו, ויוסף לפרעה וצדקיהו לנבוכדנצר לא בטלו בלבם. ודין זה אפילו קיבל הנאה ממנו ובכל תוקפי חיזוקי השבועה כל שיד חזקה באמצע מבטל בלבו ואין כאן שבועה, לזה חששו אבימלך וכו' לכרות ברית עם יצחק בגרר תחת ממשלתו כי יכול יצחק לבטלה מלבו מדין נשבעין לאנסין לזה נתחכמו לכרות ברית במקום שהם בו עתה שלא היתה שליטת אבימלך עליו, וכן מוכח מדברי רמב''ן, והוא אומרו **תהי נא** פי' עתה תהיה האלה ולא במציאות הקודם, ובזה אין לחוש לביטול השבועה בלב. וטעם אומ' כי עצמת ממנו וגו'. הוא טעם מושאל ולא רצה לגלות לו הטעם, או לבל יפציר בהם בצדדי הטעם וכי יספיק בבריתו שם וכדומה, גם היו להם טעמים אחרים כאשר אבאר בדבריהם לזה אמרו לו טעם מוחלט:
@44 **בינותינו בינינו וביניך וגו'**. טעם שהאריך לומר בינותינו וגו', נתכוון לחזק ברית אברהם ולהוסיף ברית מחדש עם יצחק, והכונה בזה לדעת ברית הראשונה של אברהם האם עומדת לנס, ויש בזה תוקף משבועה של יצחק כי כבר נפטר אברהם ואין מציאות להתרתה לבנים ולקיים כל דבר נשבע יצחק בתנאים אשר ירשום. ואולי כי חש אבימלך גם כן שיתן ה' מתנה מחדש ליצחק וינחילנה לעשו ועשו אינו זרעו של אברהם דכתיב (כא יב) כי ביצחק יקרא לך זרע ולא כל יצחק, ואם יתן יצחק לעשו ארץ פלשתים לא יזכה אבימלך בדינו עם עשו מצד ברית אברהם כי יאמר זו מתנה חדשה נתן ה' ליצחק אחרי מות אברהם ויצחק נתנה לעשו ואין מידו מציל. לזה נתחכם להשביע יצחק ושבועת יצחק תחול גם על עשו כי זרעו יקרא הגם שאינו נקרא זרעו של אברהם. וטעם שלא הזכיר הדורות, כבר רמזו אותם באומרם בינותינו וגו' ופי' רז''ל (רש''י) שבינותינו וגו' ושם נאמר לי ולניני ולנכדי:
@44 **עוד** ירמוז באומרו **בינותינו** וגו' פי' שיהיה הברית בפני רבים לא שיכרות ברית לאבימלך בינו ובינו אלא ביניהם יהיו כולם יחד, והכוונה בזה כדי שיהיה בפני רבים, ואמרו בינינו עוד לרמוז שתהיה הכונה על דעתם כדי שיהיה על דעת רבים:
@45 **אם תעשה עמנו**. דקדקו לומר נוסח וסדר הברית אשר יכרות להם שהוא בשביל הטובה, והוא אומרו **אם תעשה עמנו רעה כאשר** וגו' פי' תהיה השבועה בעד הטובה שקבלת ממנו, ובזה יש טעם להפסקת הכתובים בסדר זה, שמן הראוי היה לו להפסיק בתיבת כאשר וגו' ותיבת אם תעשה עמנו רעה היו נסמכים בפסוק שלפניו שמסיים ברית עמך שם קנו מקומם להזכיר הברית. ולפי דברינו ידוייק על נכון כי יכוון לדקדק סדר השבועה שתהיה בשביל הטובה. ואומ' **לא נגענוך** וגו' להיות שאין הכרת החסד שעשו שהיה לטובת יצחק אלא אחר הכרת פרט זה, כי תמצא שמחוקי המלכים שיתנו יד ועזר לשוכני ארצם לקנות הון לב' סיבות, הא' לאם יצטרכו להם להלוות מהם יהיה להם בית והון לעזור להועיל לפי שעה, הב' כדי שתתרומם מלכותם כי תתנשא ברבות בה אנשים עשירים ובעלי שם כי הוא מטכסיסי המלכות, ולאחד מב' סבות יאמר האומר כי טובת אבימלך ליצחק להנאת עצמו נתכוון, לזה דקדק לומר **כאשר לא נגענוך** מימינו אפי' בנגיעה שהוא דבר שאינו מחסר ממון אלא כדבר שחוזר בעיניו, ובזה באמת כי לא עשינו עמך רק טוב פי' שלל טעמים הנוגעים להם והצדיק שהכוונה היא להטיב לו דוקא, ולצד שתאמר כי היתה הכוונה למעלת המלכות הנה שלחנוך אתה וממונך והוא אומרו **ונשלחך בשלום** פי' ובממונך, הראת לדעת כי אין כונתינו בהטיב עמך לטכסיסי המלוכה ומעתה לא היה מציאות להצדיק הטוב ההוא כי נתכוונו לטובתו אלא אחר ששלחוהו הוכרו הדברים כנים. ובזה נתנו תוספת טעם גם כן למה ששלחוהו כי הוא זה דבר המעמיד לטובת הנאה המקיימת השבועה וכל זה נכלל בכלל אומרו ראו ראינו:
@45 **וראיתי** לרז''ל שאמרו (ב''ר פס''ד) וז''ל מלמד שלא עשו עמו טובה שלמה ע''כ, ולכאורה דבריהם רחוקים ביותר כי הם באו לרצותו ולהראותו חיבה יתירה ויאמרו אליו הפחתת הטוב, ולמה שכתבתי כי כונתם היא כדי שתהיה השבועה בשביל טובה יהיו דבריהם ז''ל מאירים כשמש. כי אמרו שהטובה שהטיבו עמו לא היתה מוחלטת להטיב אליו אלא לתכלית המקווה ממנו להם שהוא הברית אשר שואלים ממנו ונכון וכפטיש יפוצץ:
@45 **ואומרו אתה עתה ברוך ה'** פי' שלא אירע לו רע מאמצעות ששלחוהו שהרי הוא מבורך כמו שהיה קודם, והכוונה בזה שלא נתבטל הטוב ההוא שבעדו אתה נשבע לנו:
@45 **ודע** שהגם שכתב הריב''ש שאינו קרוי בשביל טובה אלא אם היתה הטובה בעת השבועה הוא הדין אם בשעת השבועה ברור שנשבע בעד טובה שכבר עשה לו, הרי זה דומה לזוקף עליו הטובה בחוב ובעד ויתור החוב נשבע:
@45 **עוד** ירצה לתת טעם שאינם מחזירים אותו לארץ, כי הוא ברוך ה' אדרבה ביותר מעלה מקודם כי עד עתה היתה השפעתו מאמצעות העיר שהיא תחת ממשלת שרי מעלה מה שאין כן עתה שהוא מקום לעצמו השפעתו היה שלא על ידי אמצעי אלא ברוך ה':
@45 **עוד** ירצה לשלול טענת סתירת ההטבה כי לא מהם היה המושג אליו הטוב אלא מה' והראיה הן היום במקום שהוא בו מבורך בכל מדה טובה, לזה אמרו **אתה עתה ברוך ה'** פי' עתה אחר שהטבנו לך באמצעות המוכן מצא מקור הברכות לחול עליך ברוב טוב, ובאופן זה השביעו בכל תוקף שאין מציאות להתיר אבל זולת זה היה יכול להתיר, והגם דאמרינן בפרק השולח דף מ''ו לסברת חכמים שחולקים על ר' יהודה שטעם שלא הכו ישראל הגבעונים הוא משום קדושת ה' ופרש''י שלא יאמרו הנכרים עברו בנ''י על שבועתם, הרי דהגם דישנה להתרה לצד דהוי חילול ה' בדבר לא יתיר, אין זה מעיקר התורה אלא גדר. ועוד כבר כתבתי באורך בהלכות נדרים בפרט זה כי דווקא בשבועה שהיא מפורסמת כההוא של גבעונים וכמו שדייקתי שם מדברי רש''י:
@45 **ועוד** לו יהיה שסוברים חכמים שאין לחלק בכל שבועת נכרים, הרי יש סברת ר' יהודה שאין מחלק בין נכרים לישראל שיודעים הנכרים שיש התרה לשבועה ואין כאן חילול ה', ולזה נתחכם אבימלך להשביעו שבועה שאין לה התרה גם לסברת ר' יהודה:
@52 **ויהי כי זקן יצחק**. טעם הודעה זו. כי זו סיבה שיטול יעקב את הברכות כשלא יכירהו. ואמר לשון צער, שהוצרך ליטול יעקב הברכות על ידי סיבה זו ולא בידיעת יצחק כי מזה סובבו כמה סיבות לבני עמנו:
@52 **את עשו**. ולא אמר אל עשו, כי לא היה רואהו לומר שקראהו אלא קרא את שמו:
@52 **בנו הגדול**. נתינת טעם למה לא קרא ליעקב, כי זה הבכור, ואולי שלא ידע מהמכר. וטעם יצחק שהיה חפץ לברך עשו הרשע, כי חשב שבאמצעות הברכות יתהפך למדת הטוב ויטיב דרכיו כי הצדיקים יכאבו בעשות בניהם רשע והיה משתדל עמו להטיב, ואפשר שהיה מועיל, ותמצא שאמרו ז''ל (ב''ר פ''פ) כי נענש יעקב שמנע דינה מעשו שאפשר שהיתה מחזירתו למוטב, הרי שאפשר לו לחזור למ וטב:
@56 **ורבקה שמעת וגו'**. פי' מודיע הכתוב כי רבקה נביאה היתה ושומעת תמיד בדברי יצחק וגו' הגם שלא ידבר בפניה והבן. ולזה אמר **ורבקה שומעת בדבר** וגו' ולא אמר ותשמע רבקה וגו' ולא אמר היתה שומעת וגו'. ואולי כי דבר אליו יצחק בלט ולזה האמין בבוא יעקב כי הוא עשו כי באוזן עשו דבר, והגם כי עיני יצחק כבדו, עם כל זה הודיעו כי דברי סתר אליו. ואולי כי לזה רמז הכתוב באומרו **ויקרא את עשו** וגו' **ויאמר אליו בני ויאמר הנני** פי' נתיחדו לדברים נכמסים:
@57 **ורבקה אמרה**. אמר תוספת וא''ו כי הסכימה היא לרוח הקודש השרויה עליה:
@57 **לאמר הנה וגו'**. פי' שלא יחשוב כי כבר עבר זמן ארוך מעת דבר יצחק לעשו ויאמר כי לא יספיק הוא לעשות מצותה של רבקה עד שכבר עשו עשה מעשהו, לזה אמרה **לאמר** הנה פי' אמרה לו כי באותה שעה שמעה ויש זמן:
@57 **אחיך לאמר**. פי' לא אחיך בדומה לך אלא באמירה יאמר אליו שם אחיך אבל לא ידמה חושך לאור עולם:
@57 **עוד** נתכוונה באומרה **לאמר** שלא להוציא דבר שקר מפיה כי לא אמרה הדברים בדקדוק כיציאתם מפה יצחק, לזה אמרה לאמר הביאה וגו' פי' מה שנתכוין באמירתו הוא זה, וזולת לאמר יהיה נשמע כי אומרת דבריו בדקדוק:
@59 **ועתה וגו'**. פי' באותה שעה ימהר להביא מן המוכן גדיי עזים:
@59 **שמע בקולי**. פי' הגם שיש בדברים אלו כגניבת הדעת, עם כל זה יש לך לשמוע בקולי פי' מלבד חיוב מצות כיבוד אב ואם שהיא מצות עשה גם היא נביאה וכתיב בדברי נביא אמת (שופטים יח) אליו תשמעון לזה אמרה **שמע בקולי**, וכבר כתבנו (לעיל טז ה) שיצטדק נביא באומרו לעבור על מצוה ממצות התורה לפי שעה:
@64 **עלי קללתך בני וגו'**. טעם אומרה **בני** אחר שעמו היתה מדברת. פי' מה שהוצאת אתה מפיך עתה, ושיעור התיבה קללה שקללת בני, והוא על דרך אומרם ז''ל (מכות יא.) קללת חכם אפי' על תנאי וגו', ולזה חששה ולבשה היא גרם קללה שהוציא מפיו, ואם לא (היה) [היתה] אומרת בני היה נשמע קללה שיקללו אביו:
@64 **וראיתי** לתת טעם לאהבת רבקה ליעקב, לצד כי עיני כל אליה יצעירו כי ממנה יצא רשע הוא עשו, והנה לטבע הרגיל החלקים יאהבו חלק אל חלקיו, וזה מהבוחן, לזה גלתה דעתה כי לא כן הוא ומעשיה מוכיחות כי מקורה ברוך וחלק הטוב חלקיה וטבעה אל אהבת הטוב ירוץ, ולזה תמצא שירבה הכתוב לומר בכל פועל ופעול ממנה יעקב בנה ללא צורך וכוונתו היא להגיד כי ממנה אורחות צדיק ויסודו מיסודה גם כן נבנה, ומוצאו של עשו לא מבחינתה של רבקה ח''ו. גם יש סוד בדבר כידוע ליודעי חן כי הוא זוהמת הקדושה אחר צירופה באש הגבורה שבבחינת יצחק אבינו והבן. והגם שכתבנו למעלה (כ''ה כ') כי סיבתו הוא היותה אחות לבן, דבר זה לא יהיה סיבה לבחינת רבקה כי ממנה היא כמעשיה ח''ו, ופרט זה הוא מהמוסגל להפריד הזוהמא בפני עצמה ולעמוד קו הטוב על תילו הוא יעקב אבינו ששופריה מעין שופריה של אדם הראשון (ב''מ פד.) והוא סוד והבן:
@66 **ותלבש וגו'**. פי' הלמתם עליו בתיקון הלבישה הגם שהיו גדולים תקנתם לקטן:
@70 **אנכי עשו בכורך**. פי' להיות שקנה הבכורה מעשו הנה הוא נעשה עשו לצד בחינת הבכורה כי (לא) [לה] יקרא עשו בכורו. ואומרו **עשיתי כאשר דברת אלי** פירוש כי טעם שצוה לעשו הוא כי הוא בנו הבכור וכיון שנטל הבכורה כאילו הדבר בא אליו:
@74 **ולא הכירו כי היו וגו'**. ואף על פי כן דחה שמיעת קול מלפני חוש ההרגש כי הקול יכול להשתנות, או לצד משמיע, או לצד שומע, מה שאין כן הרגשת שערות הידים הוא סימן מובהק:
@74 **ויברכהו**. פי' לצד כי מקודם שמששו וידע כי עשו הוא לא היה לו דבר מכחיש לקול הבא לאזניו שאינו עשו והרי זה מתעתע ונכנס בחששת יעקב שאמר והבאתי עלי וגו', והגם שלא מצינו לו שקללו אף על פי כן הכין לבו לשנאתו, ודבר זה בצדיקים יפעיל, וצא ולמד מרז''ל (ב''מ פד) אם היו מקפידים בלבם על הזולת היו מביאים עליו קללה, לזה כשראה ידיו שעירות ויברכהו להסיר ההפך שהומשך מקודם:
@75 **ויאמר אתה זה וגו'**. פי' מצדיק דבריו כי הוא עשו לא שואל. ותשובת יעקב היא בלשון פשיטות אני:
@75 **עוד** ירצה באומרו **אתה זה** להיות שהיה קולו מגיד כי יעקב הוא לזה נתכוון לברך לגוף המחליט כי הוא עשו, ולזה אמר אתה זה מורה באצבע לאשר יגיד חוש המישוש והיה מלביש הברכות בדעתו במה שלפניו בלא שום מחשבה מי הוא, וזה הוא לטובה אות שקבל הברכות יעקב בכוונה אליו, והגם שגמר אומר יצחק והזכיר עשו, עם כל זה בשעת הברכה לא היה מברך אלא זה שלפניו:
@78 **ויברכהו ויאמר ראה וגו'**. אומרו **ראה** לא לשון ראיה אלא חשיבות והכוונה ראוי הוא ריח בני וחשוב לדמותו כריח שדה אשר וגו':
@79 **ויתן לך האלהים**. טעם אומרו וא''ו בתחילת ענין, להיות שקדם ואמר ויברכהו הוסיף עוד לומר ויתן לך וגו', ומה שלא פי' הברכות הרמוזות בויברכהו, אולי שיכוין על דרך אומרם ז''ל (ב''ר פל''ט) שמפתח הברכות נתנו ה' לאברהם ואברהם ליצחק (שם פי''א) ועתה מסרם יצחק ליעקב, והוא אומרו **ויברכהו** פי' מסר לו הברכות שיהיו ברש ו ת ו:
@79 **עוד** ירצה שברכו ברכות רוחניות וגשמיות כנגד הרוחניות אמר בהעלם ויברכהו, וכנגד הגשמיות אמר **ויתן לך** וגו' בתוספת וא''ו לומר מלבד עולם העליון אשר בחר אברהם לבניו שהוא עיקר תכלית זרע ישראל עוד יתן לו בעולם הזה וכו':
@79 **עוד** ירצה על זה הדרך לא מלבד מדת הרחמים אלא גם מדת הדין תסכים על נתינה זו והוא אומרו **ויתן לך האלהים** פירוש גם מדת אלהים:
@80 **יעבדוך וגו'**. אולי כי המלך לא יעלה מס הנוגע לו בין העם, וכדומה לזה ימצא בזמן שישראל משועבדים לאומות העולם המלכים שבהם שהם בעלי תורה פטורים מהמס (עזרא ז), ומה שאמר אחר כך (מ) ואת אחיך תעבוד והוא היה מלך חוזר אל בני עשו:
@80 **הוה גביר לאחיך**. פי' אחיו ממש לא יהיה לו לעבד אלא שיהיה הוא גביר לו, אבל הבאים אחריו ישתחוו לו והוא אומרו **וישתחוו לך בני אמך**:
@80 **עוד** ירצה שיהיה הוא מתגבר עליו באמצעות עבודת הקודש אז ישתחוו לו בני וגו', כי זולת זה לא ישתעבד אח לאחיו, ולזה תמצא כי במעט התרשלות שהיו מתרשלים ישראל בעבודת ה' תכף ומיד (מ''ב ח) ויפשע אדום:
@80 **אורריך וגו' ומברכיך וגו'**. פי' אורריך לעתיד ארור הוא מעכשיו ולא יקום לארר, ומברכיך ברוך הוא מקודם כדי שתחול ברכתו עליך:
@80 **וטעם** אומרו מברכיך לשון רבים ולא ברך אלא לאחד, גם הזכיר מאררים רבים וארור לאחד, נתכוון לשלול חלק מהמאררים שאינו ארור והוא אחיה השילוני וכיוצא בו, לזה אמר ארור ולא ארורים כולם, ובמברכים ג''כ יש מהמברכים שאינו בכלל ברוך והוא בלעם הרשע שהגם שברך לא יבורך, ולזה אמר מברכיך יש בהם חלק אחד שהוא ברוך ולא כולם לשלול הנזכר, ואמר **ומברכיך** בתוספת וא''ו לרמוז על מין מקלל שישנו בכלל ברכה והוא המכוון לברך, על דרך אומרם רבנן לר' אלעזר בן רשב''י (מוע''ק ט:) תזרע ולא תחצד וכו', וזה הוא שיעור הכתוב **אורריך ארור ומברכיך** פי' ואותם אורריך אם הם מכוונים למברכיך ברוך:
@81 **ויהי כאשר כלה**. טעם אומרו **ויהי** לשון צער, כי התורה מצטערת על אשר כלה ולא ברך כל הברכות שהרי מצינו שברך לעשו אחר כן, ואם היה מברך אותם הברכות הנשארות ליעקב כבר אבדה תקות אדום:
@81 **ויהי אך יצא וגו'**. טעם אומרו **ויהי** לשון צער, גם אמר אך, גם כפל לומר יצא יצא. נתכוון לומר שעדיין היה מעוכב ביציא' יעקב והוא אומרו **אך יצא** מיעט ביציאה אלא לסיבה שאירעה יצא, והסיבה היא מה שהודיע הכתוב לבסוף באומרו ועשו אחיו בא מצידו ולסיבה זו מיהר לגמור היציאה והוא אומרו **יצא**, ורמז אל הצער שחש יעקכ שימצא כגנב במחתרת בפני אביו כשהרגיש בביאת עשו, ורז''ל (ב''ר פס''ו) דרשו באופן אחר:
@84 **ויחרד יצחק וגו' גם ברוך וגו'**. טעם ב' דברים הפכיים בנושא אחד, כי מתחלה חרד על הרמאות ואחר כך חש למה שקדם ואמר בברכתו אורריך ארור וברכהו, קודם לא ידע מי הוא וחרד וחש לאדם אחר, וכשהתבונן בדבר והשכיל כי הוא יעקב ברך אותו כי הריח מריח בגדיו וידע הפרש שבינו לבין עשו וחתם על הברכות, גם חש למה שקדם לומר אורריך ארור לזה ברכהו:
@87 **ויאמר הכי קרא וגו'**. פי' מתמיה הכי קרא שמו יעקב ומשמעות השם לא יגיד אלא עוקבה אחת והוא עקבני זה פעמים, שאילו היה שמו עקבות או עוקבות היה עוקבו פעמים:
@87 **או** ירצה על זה הדרך **הכי קרא שמו יעקב** ולא אמר עקבה או עקב שאז לא יגיד אלא על עוקבה אחת אבל יעקב יגיד על התמידות ולזה עד עתה כבר (עברו) [עקבו] פעמים:
@88 **ויען יצחק**. הנה עדיין היה לו מציאות לברכו אלא לצד שהכיר בו וידע כי הוא ראוי לקללה ואויב ליעקב חש לברכו כי הוא הפך מה שקדם לומר ליעקב אורריך ארור, ולזה היה מתנצל מעשו מלברכו. ולזה כפל לומר הכתוב ויען ויאמר לעשו פי' שמענה זה אינו אלא לאמר ואין כן הוא האמת בדעת יצחק:
@90 **ויען יצחק אביו**. פי' נתינת טעם למה חזר לברכו. לצד רחמי אב כשבכה נכמרו רחמיו:
@90 **הנה משמני**. פי' אין לו אלא מה שלפניו לא כיעקב שאמר ויתן לך בתוספות וא''ו פירוש מלבד עולם הנצחי וכמו שפירשנו:
@91 **ואת אחיך וגו' והיה כאשר וגו'**. רבו הפירושים בזה. ואפשר לומר שנתכוון לומר על זה הדרך שכל הברכות שברכו יהיה כאשר יעבוד את אחיו. וכאשר ירד ממדרגה זו, או ירצה לשון רדוי כאשר תהיה רדוי ואבוד, יקדים לפרוק עולו ואחר כך תרד ויהיה בית יעקב אש וגו' ובית עשו לקש (עובדי' א) ויכלה. ולזה דקדק לומר **והיה** לשון שמחה כי אז ישמחו השמים ותגל הארץ:
@91 **או** ירצה **והיה** כאשר תשלוט אתה בעולם לא תהיה מעלתך עליו אלא ופרקת עלו מעל וגו' לא הוא ישלוט בך ולא אתה תמשול בו, ומה שמשל אחר כך עונות הטו אלה:
@92 **יקרבו ימי אבל וגו'**. פי' אחר שימות ויקבר שאז הוא התחלת ז' ימי אבילות וחש שלא יהרגנו בעוד שלא נקבר אביו כי המת ידע קודם שיסתם הגולל (שכת קנב:):
@93 **עשו בנה הגדול**. אומרו הגדול, לומר כי הוא יכול עשות אשר זמם לעשות לאחיו, בנה הקטן פי' לצד היותו קטן ממנו ביכולת:
@93 **מתנחם לך**. פי' מקבל נחמה על אשר עשית לו, להורגך, ובזה תחזור לו הבכורה והברכה:
@94 **ועתה בני**. פי' על דרך אומרם ז''ל (אבות פ''ב מ''י) ושוב יום אחד לפני מיתתך ופי' כי אין אדם בטוח בחייו אפי' יום אחד ובזה יהיה תמיד בתשובה, לזה אמרה **ועתה** וגו' **קום ברח** וגו' פי' ועתה תכף ומיד, והגם שלא אמר עשו אלא יקרבו וגו', אפשר שימות יצחק באותו שעה ויוציא מחשבתו לפועל:
@94 **ברח לך אל לבן**. כי הוא יעמוד נגד עשו אם ילך להורגך:
@95 **עד אשר תשוב וגו'**. פי' בעבור זמן על המאורע החמה מעצמה מתקררת מרתיחתה, ואומ' עוד **עד שוב אף אחיך** פי' כי לא יועיל זה לבד אלא עד שוב אף אחיך ממך פי' שהגם שיזכירוך לפניו לא יחרה אפו, והוא אומרו **ממך** אז הוא סימן ששכח המעשה וכו'. **ושלחתי** וגו' פי' אני אשלח אחריך כשיהיה כן אבל אתה לא תבא בשום אופן:
@96 **גם שניכם וגו'**. פי' לו יהיה שימות גם הוא, או על ידך או על ידי גואלי הדם, אף על פי כן אין מרפא לשברך במה שימות גם הוא עמך ביום אחד, ולעולם אינה מקפדת אלא על מיתת יעקב ולא על עשו:
@97 **קצתי בחיי וגו'**. לא רצתה לגלות הדבר ליצחק משום איסור רכילות ואמרה סיבה אחרת, אבל מה שגילתה ליעקב אדרבה קיימה מצות (ויקרא יט) לא תעמוד על דם רעך:
@102 **וישלח יצחק וגו'**. צריך לדעת למה הוצרך לומר **אחי רבקה** מי לא ידע בזה, ומה גם שבסמוך אמר כן. ועוד אומרו **אם יעקב ועשו** הם דברים יתירים:
@102 **אכן** בא הכתוב לתת טעם ליצחק אבינו ששלח בן צדיק לאדם רשע מפורסם לבן הארמי. והגם שאברהם שלח ולקח רבקה לא היה בתואל מפורסם ברשע כלבן. ועוד שלא אמר בפי' אברהם שיקח בת בתואל מה שאין כן יצחק שצוה ליעקב שיקח אשה מבנות לבן הרשע, לזה אמר **אחי רבקה** ושניהם יצאו מבתואל הרשע וכמו כן יצא מלבן בת צדקת, גם אין להוכיח שלא יצא שלשלת שורש קדושה מאדם רשע, לזה אמר **אם יעקב ועשו** פי' הרי שיצתה שלשלת הקדושה מאב רשע, גם כן אין להחליט ולומר כי להיות לבן רשע לא יצא ממנו בנות כרבקה:
@102 **ויש** לך לדעת כי דוקא בימים ההם שעדיין לא נתבררו הנשמות הקדושות ממקום שבייהם, והוכרה משפחת אברהם כי שם קנתה לה הקדושה מקום, והיה לה לאות עולם אברהם ושרה כי הם גרים ראשונים וכל אשר יתגייר מהאומות בכל זמן יקרא אברהם ונקבה שרה. לזה מין הקדושה יחפש אחר מינו, כי אחד היה אברהם ולא הושלם בנין הקדושה בזכרים ובנקבות כי לא הוליד אלא את יצחק ולא הוליד נקבות עמו. ואולי כי לזה אמר הכתוב (כ''ה י''ט) אברהם הוליד את יצחק פי' לבדו בלא בת זוג, וכמו כן יצחק לא היה לו בנות כי ניצוצות הקדושה הנקבות עודם בארץ שבי, לזה שלחו יצחק לחזר אחר אבידתו:
@102 **אך** זה היום שקוינוהו כי פרחו שורש הקדושה הן בני ישראל ופרח מטה עוז תפארה והוכר אילן החיים חלק ה' עמו יעקב חבל נחלתו הן הנה המובהקים בקודש ולא יסוב אדם ממטות בני ישראל למשפחות הארץ, ואם נשאר מניצוצי הקדושה בתוך העמים הרי הם ביציאתם לעולם מתאספים ובאים ואחר גרותם יאמנו כי אבודים היו ולנו הם:
@102 **וטעם** הכנעני אשר הקפיד אברהם לבלתי קחת לו אשה מהם גם יצחק צוה ליעקב על זה, רבותינו אמרו (ב''ר פנ''ט) כי הוא ארור וזרע אברהם ברוך וכו', ודבריהם סתומים הם, ולפי מה שכתבתי מצינו עיקר הטעם נכון כי טעמו של אברהם הוא כי הוא מושלל מנפשות הקדושות וכל בנותיו חלק רע ומתועב, לזה החליטו לבלתי קחת ממנו כי לא ימצא בו דבר קדוש, והוא סוד אומרו (לעי' ט, כה) ארור כנען פי' מושלל בהחלט ממין הקדושה:
@102 **ותמצא** כי ממין האומות עד היום עודם מתקבצים ובאים גרים וחסים בצל הקודש אשר לא שמענו מימי קדם כי נתגייר גר כנעני כשאר העמים וזה יגיד דברינו, ואולי כי לזה יצו האל (דברים כ) לא תחיה כל נשמה מז' עממים, ודקדק לומר כל נשמה לתת טעם למצות לא תחיה כי אין בהם נשמה פי' נפש קדושה שיתייחם אליה שם נשמה לחוס עליה להחיותה כעמון ומואב והבן:
@102 **ואחרי** הודיע אלהים אותנו את כל זאת צריך לתת לב מדוע אנו בעונות משועבדים לכנען, אחר שידענו נאמנה שהשיעבוד הוא לברר הניצוצות של הקדושה שבתוך הקליפה ובכנענים אין בהם ניצוץ קדוש לרדת אחריו בגלות, ותמצא כי מצרים אשר נתרוקנה מהניצוצות כאומרם ז''ל (פסחים קיח.) לא יצאו ישראל עד שעשאוה כמצודה שאין בה דגן וכמצולה שאין בה דגים דכתיב וינצלו את מצרים צוה ה' לבל יבאו שמה וכמבואר הטעם בדברי האר''י ז''ל (שער הגלגולים), ואם כן איך יהיה שנסבול את כל עוצם הגלות הזה מבלי היות בו ניצוצי הקדושה:
@102 **אכן** יתבאר הדבר על דרך אומרם ז''ל (ליקוטי תורה מקץ) כי יש שני מיני ניצוצי הקדושה שבויים בקליפה האחת נשמות יקרות ויוצאות באמצעות הלידה כאברהם וכשרה וכרבקה ורחל וכנשמת ר' חנינא בן תרדיון שיצא משכם עם דינה וכרות ממואב וכנעמה מעמון וכאונקלום הגר וכדומה. והב' הוא מין ניצוץ של קדושה הדבוק בקליפה ואינו יוצא כלל אלא מעורה בקליפה ואין לו מציאות ליפרד ממנו אלא כאשר ייצר לישראל על ידי צער או על ידי הכאה שבאמצעות דבר זה תהיה נפרדת הקדושה וחוזרת לשרשה. ומעתה יש טעם לגלות זה כי תאוה לברר בחינת ניצוצי הקדושה שאינה נפרדת אלא על ידי צער שמצטערים ישראל. ועל גלות הזה אמר הכתוב (עובדיה א) וגלות החל הזה לבני ישראל אשר כנענים עד צרפת, שהכתוב קראו החל מלשון נהייתי ונחליתי (דניאל ח) כי השגת תכלית הגלות ביניהם הוא באמצעות הצער ולזה הוא משונה מכל הגליות כאשר ראינו בעינינו. ואמר אשר כנענים ולא אמר בכנענים, וגם אמר כנענים לשון רבים, אולי כיוון על הניצוצות של הקדושה שלהיותם עתה בתוך קליפת כנען יקראו בשמו כנענים, ושיעור הכתוב על זה הדרך גלות החל הזה שהוא גלות ישראל הוא לסיבת בני ישראל שהם עתה נקראים כנענים על מקום שהם בו:
@103 **וירא עשו כי ברך וגו'**. פסוק זה אין לו גזרה ואם גזרתו הוא וילך עשו אל ישמעאל היה מספיק בפסוק שאחרי זה וירא עשו כי רעות:
@103 **אכן** כוונת הכתוב היא להודיע שידע עשו הליכת יעקב ואופנה, כי הלך במצות אביו ואמו וגם למצות קיחת אשה וגם ברכוהו בשלחם אותו, כי לצד זה לא רדפו שידע שימנע מידו, היותו הולך לב' מצות כבוד אב ואם ולקיחת אשה. והגם ששלח אליפז כאומרם ז''ל (רש''י כ''ט י''א), אפשר שבחן כי הוא נוצח בדרך ליעקב, ומעשה אבות עשו בנים אשר קדם בדרך לישראל, וחשב עשו כי גדול כח אליפז מכחו בבחינת רדיפה בדרך ליעקב ובניו:
@105 **וירא עשו כי רעות וגו'**. יגיד הכתוב כי לא חש עשו אלא לצד הקפדת אביו עליהם, אבל זולת זה למה שהם בחינת הרע לא חש שאין נפשו מתעבתן. וממוצא דבר גם כן אתה יודע שלא הועיל טעם היותם רעות בעיני יצחק אלא לבל יוסיף מהם אבל לגרש אותן שהיו כבר אצלו לא. ואולי שכל הרגשתו לא היתה אלא שמא יתפקעו ברכותיו לצד בנים אשר יהיו לו מבנות כנען לזה לקח מבנות ישמעאל כדי שיתקיימו הברכות באמצעות הבנים שיהיו לו מהם:
@105 **חסלת פרשת תולדות**
